window.HB3DATA={"sp":{"wang":"王老师","han":"汉汉","xs":"学生们","ming":"阮明","hua":"黎花","da":"陈大中","anna":"安娜","qiu":"阮秋","liu":"刘先生","xue":"小雪","tian":"小天","seller":"售货员","waiter":"服务员","doc":"张医生","ye":"爷爷","nai":"奶奶","tx":"同学","zhang":"老张","siji":"司机","staff":"工作人员"},"L":[{"n":1,"zh":"我们去机场接你们","py":"Wǒmen qù jīchǎng jiē nǐmen","vi":"Chúng mình ra sân bay đón các bạn","goal":["Miêu tả ngoại hình người khác (cao, gầy, tóc ngắn…).","Dùng cụm cố định 看上去 / 看起来.","Dùng đại từ nghi vấn với nghĩa phiếm chỉ (什么, 谁, 哪儿…).","Dùng nhiều định ngữ cùng lúc trước danh từ."],"w":[["帮助","bāngzhù","động từ","giúp đỡ"],["不见","bújiàn","động từ","không thấy, mất"],["带","dài","động từ","mang, dẫn"],["丢","diū","động từ","mất, đánh rơi"],["短","duǎn","tính từ","ngắn"],["发现","fāxiàn","động từ","phát hiện"],["服务台","fúwùtái","danh từ","quầy phục vụ"],["好像","hǎoxiàng","phó từ","hình như"],["号码","hàomǎ","danh từ","số, mã số"],["护照","hùzhào","danh từ","hộ chiếu"],["接","jiē","động từ","đón"],["米","mǐ","lượng từ","mét"],["年轻","niánqīng","tính từ","trẻ"],["身高","shēngāo","danh từ","chiều cao"],["瘦","shòu","tính từ","gầy"],["头发","tóufa","danh từ","tóc"],["箱子","xiāngzi","danh từ","va li, hòm"],["像","xiàng","động từ","giống"],["行李","xíngli","danh từ","hành lý"],["以为","yǐwéi","động từ","tưởng (là)"],["应该","yīnggāi","động từ năng nguyện","nên, chắc là"],["站","zhàn","động từ","đứng"],["长","zhǎng","động từ","lớn lên, mọc, trông"],["着急","zháojí","tính từ","sốt ruột, lo lắng"],["照片","zhàopiàn","danh từ","ảnh"],["中间","zhōngjiān","danh từ","ở giữa"],["重要","zhòngyào","tính từ","quan trọng"]],"p":[],"t":[{"s":"Ở sân trường, Minh thấy một bạn đi cùng Lê Hoa.","bg":"campus","l":[["ming","那个人是大中吗？他怎么和黎花在一起？","Nàge rén shì Dàzhōng ma? Tā zěnme hé Lí Huā zài yìqǐ?","Người kia là Đại Trung à? Sao cậu ấy lại đi cùng Lê Hoa?"],["da","我在这儿呢！那不是我，那是黎花的哥哥。","Wǒ zài zhèr ne! Nà bú shì wǒ, nà shì Lí Huā de gēge.","Mình ở đây mà! Đó không phải mình, đó là anh trai của Lê Hoa."],["ming","哦，我以为是你。你们长得有点儿像。","Ó, wǒ yǐwéi shì nǐ. Nǐmen zhǎng de yǒudiǎnr xiàng.","Ồ, mình tưởng là cậu. Hai người trông hơi giống nhau."],["da","是有点儿像，不过他比我高，身高一米八左右。","Shì yǒudiǎnr xiàng, búguò tā bǐ wǒ gāo, shēngāo yì mǐ bā zuǒyòu.","Đúng là hơi giống, nhưng anh ấy cao hơn mình, khoảng 1 mét 8."],["ming","他看上去也比你瘦一点儿。","Tā kàn shangqu yě bǐ nǐ shòu yìdiǎnr.","Trông anh ấy cũng gầy hơn cậu một chút."]]},{"s":"Ở sân bay, Lê Hoa không thấy va li của mình.","bg":"airport","l":[["hua","我的行李怎么还没出来？是不是丢了？","Wǒ de xíngli zěnme hái méi chūlai? Shì bu shì diū le?","Sao hành lý của mình vẫn chưa ra nhỉ? Có phải bị mất rồi không?"],["anna","你的箱子长什么样？","Nǐ de xiāngzi zhǎng shénme yàng?","Va li của cậu trông thế nào?"],["hua","黑色的，上面有我的名字和手机号码。","Hēisè de, shàngmian yǒu wǒ de míngzi hé shǒujī hàomǎ.","Màu đen, bên trên có tên và số điện thoại của mình."],["anna","我好像在哪儿看见过一个，是不是被别人拿走了？","Wǒ hǎoxiàng zài nǎr kànjiànguo yí ge, shì bu shì bèi biérén názǒu le?","Hình như mình đã thấy một cái ở đâu đó, có phải bị người khác lấy nhầm không?"],["hua","怎么办？里面有很重要的东西。","Zěnme bàn? Lǐmian yǒu hěn zhòngyào de dōngxi.","Làm sao bây giờ? Bên trong có đồ rất quan trọng."],["anna","别着急，我们带上护照去服务台问问。","Bié zháojí, wǒmen dàishang hùzhào qù fúwùtái wènwèn.","Đừng lo, chúng mình mang hộ chiếu ra quầy phục vụ hỏi xem."]]},{"s":"Cô Vương và Minh ra sân bay đón người quen.","bg":"airport","l":[["wang","飞机已经到了一会儿了，你看见她们了吗？","Fēijī yǐjīng dào le yíhuìr le, nǐ kànjiàn tāmen le ma?","Máy bay đến được một lúc rồi, em thấy họ chưa?"],["ming","还没有，她们应该马上就出来了。","Hái méiyǒu, tāmen yīnggāi mǎshàng jiù chūlai le.","Chưa ạ, chắc họ sắp ra rồi."],["wang","我们站中间吧，这样她们容易看见我们。","Wǒmen zhàn zhōngjiān ba, zhèyàng tāmen róngyì kànjiàn wǒmen.","Chúng ta đứng ở giữa đi, như vậy họ dễ nhìn thấy mình."],["ming","你看，那个穿红衣服、短头发的年轻人是不是阿秋？","Nǐ kàn, nàge chuān hóng yīfu, duǎn tóufa de niánqīngrén shì bu shì Ā Qiū?","Cô xem, người trẻ tóc ngắn mặc áo đỏ kia có phải chị Thu không ạ?"],["wang","是她！她看起来比照片上还年轻。","Shì tā! Tā kàn qilai bǐ zhàopiàn shang hái niánqīng.","Đúng rồi! Trông chị ấy còn trẻ hơn trong ảnh."]]}],"g":[{"t":"Cụm cố định 看上去 / 看起来","e":"看上去 / 看起来 + tính từ / cụm từ: nhìn qua thì thấy, trông có vẻ. Dùng để nói nhận xét dựa vào vẻ bề ngoài.","x":[["他看上去比你瘦一点儿。","Tā kàn shangqu bǐ nǐ shòu yìdiǎnr."],["她看起来很年轻。","Tā kàn qilai hěn niánqīng."],["这个菜看起来很好吃。","Zhège cài kàn qilai hěn hǎochī."]]},{"t":"Đại từ nghi vấn dùng phiếm chỉ (1)","e":"Đại từ nghi vấn như 哪儿, 什么, 谁 có thể không dùng để hỏi mà chỉ một người, nơi, vật không xác định: ở đâu đó, cái gì đó, ai đó.","x":[["我好像在哪儿看见过。","Wǒ hǎoxiàng zài nǎr kànjiànguo."],["你想吃点儿什么吗？","Nǐ xiǎng chī diǎnr shénme ma?"],["有谁找过我吗？","Yǒu shéi zhǎoguo wǒ ma?"]]},{"t":"Nhiều định ngữ","e":"Khi có nhiều định ngữ, thứ tự thường là: sở hữu → chỉ thị/số lượng → cụm động từ/tính từ có 的 → tính từ không 的 → danh từ.","x":[["那个穿红衣服、短头发的年轻人","Nàge chuān hóng yīfu, duǎn tóufa de niánqīngrén"],["我的一个好朋友","Wǒ de yí ge hǎo péngyou"],["一个黑色的大箱子","Yí ge hēisè de dà xiāngzi"]]}],"f":[{"s":"他___上去比你瘦一点儿。","a":"看","o":["想","长","站"]},{"s":"我___是你，原来是他哥哥。","a":"以为","o":["认为","觉得","好像"]},{"s":"别___，我们去服务台问问。","a":"着急","o":["重要","年轻","丢"]},{"s":"她们___马上就出来了。","a":"应该","o":["好像","以为","重要"]},{"s":"我们带上___去服务台问问。","a":"护照","o":["照片","号码","头发"]}],"tf":[{"t":1,"s":"那个人是大中。","py":"Nàge rén shì Dàzhōng.","a":"×"},{"t":1,"s":"黎花的哥哥比大中高。","py":"Lí Huā de gēge bǐ Dàzhōng gāo.","a":"√"},{"t":2,"s":"黎花的箱子是黑色的。","py":"Lí Huā de xiāngzi shì hēisè de.","a":"√"},{"t":3,"s":"阿秋看起来比照片上老。","py":"Ā Qiū kàn qilai bǐ zhàopiàn shang lǎo.","a":"×"}],"q":[{"s":"Chiều cao của anh trai Lê Hoa khoảng bao nhiêu?","a":"一米八左右","o":["一米六左右","两米左右"]},{"s":"Va li của Lê Hoa có gì ở trên?","a":"名字和手机号码","o":["照片","护照"]}]},{"n":2,"zh":"你们想吃什么就点什么","py":"Nǐmen xiǎng chī shénme jiù diǎn shénme","vi":"Các bạn muốn ăn gì thì gọi nấy","goal":["Gọi món, nhận xét món ăn và cách phục vụ ở nhà hàng.","Dùng câu ghép song song 又……又…….","Dùng đại từ nghi vấn phiếm chỉ dạng 什么……什么, 哪儿……哪儿."],"w":[["不用","búyòng","phó từ","không cần"],["菜单","càidān","danh từ","thực đơn"],["尝","cháng","động từ","nếm, ăn thử"],["蛋糕","dàngāo","danh từ","bánh ngọt"],["饿","è","tính từ","đói"],["方便","fāngbiàn","tính từ","tiện lợi"],["方便面","fāngbiànmiàn","danh từ","mì ăn liền"],["服务","fúwù","động từ","phục vụ"],["好久","hǎojiǔ","tính từ","lâu lắm"],["鸡","jī","danh từ","gà"],["记","jì","động từ","nhớ, ghi"],["简单","jiǎndān","tính từ","đơn giản"],["渴","kě","tính từ","khát"],["客气","kèqi","tính từ","khách sáo"],["筷子","kuàizi","danh từ","đũa"],["马上","mǎshàng","phó từ","ngay lập tức"],["热情","rèqíng","tính từ","nhiệt tình"],["勺子","sháozi","danh từ","cái thìa"],["双","shuāng","lượng từ","đôi"],["外卖","wàimài","danh từ","đồ ăn mang đi, giao tận nơi"],["碗","wǎn","danh từ","bát"],["选","xuǎn","động từ","chọn"],["饮料","yǐnliào","danh từ","đồ uống"],["用","yòng","động từ","dùng"],["又","yòu","phó từ","lại, vừa"],["员","yuán","hậu tố","người làm (việc gì)"],["张","zhāng","lượng từ","tờ, tấm, cái (vật phẳng)"],["只","zhǐ","phó từ","chỉ"]],"p":[],"t":[{"s":"Ở nhà hàng, cô Vương mời Anna và Đại Trung ăn tối.","bg":"restaurant","l":[["wang","安娜、大中，你们看看菜单，想吃什么就点什么。","Ānnà, Dàzhōng, nǐmen kànkan càidān, xiǎng chī shénme jiù diǎn shénme.","Anna, Đại Trung, các em xem thực đơn đi, muốn ăn gì thì gọi nấy."],["da","谢谢老师，我什么都可以，安娜先选吧。","Xièxie lǎoshī, wǒ shénme dōu kěyǐ, Ānnà xiān xuǎn ba.","Em cảm ơn cô, em ăn gì cũng được, Anna chọn trước đi."],["anna","我又饿又渴！好久没吃饺子了，我想要一盘饺子和一杯绿茶。","Wǒ yòu è yòu kě! Hǎojiǔ méi chī jiǎozi le, wǒ xiǎng yào yì pán jiǎozi hé yì bēi lǜchá.","Em vừa đói vừa khát! Lâu lắm rồi chưa ăn sủi cảo, em muốn một đĩa sủi cảo và một cốc trà xanh."],["wang","好，别客气，再看看还想吃什么。","Hǎo, bié kèqi, zài kànkan hái xiǎng chī shénme.","Được, đừng khách sáo, xem tiếp còn muốn ăn gì nữa."]]},{"s":"Gọi thêm bát đũa.","bg":"restaurant","l":[["wang","服务员，请再给我们一双筷子、一个勺子和一个碗。","Fúwùyuán, qǐng zài gěi wǒmen yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn.","Phục vụ ơi, cho chúng tôi thêm một đôi đũa, một cái thìa và một cái bát."],["waiter","好的，请等一下，马上就来。","Hǎo de, qǐng děng yíxià, mǎshàng jiù lái.","Vâng, xin đợi một chút, có ngay ạ."],["wang","这儿的服务员又热情又客气，菜也好吃。你们尝尝！","Zhèr de fúwùyuán yòu rèqíng yòu kèqi, cài yě hǎochī. Nǐmen chángchang!","Nhân viên ở đây vừa nhiệt tình vừa lịch sự, đồ ăn cũng ngon. Các em ăn thử đi!"],["anna","每个菜都很好吃，老师真会点菜！","Měi ge cài dōu hěn hǎochī, lǎoshī zhēn huì diǎn cài!","Món nào cũng ngon, cô gọi món giỏi thật!"],["wang","我常来这儿，服务员都记得我爱吃什么。","Wǒ cháng lái zhèr, fúwùyuán dōu jìde wǒ ài chī shénme.","Cô hay đến đây, nhân viên đều nhớ cô thích ăn gì."]]},{"s":"Ăn xong, cả nhóm nói chuyện về đồ ăn giao tận nơi.","bg":"restaurant","l":[["anna","这个鸡做得真好吃，下次我还想来。","Zhège jī zuò de zhēn hǎochī, xiàcì wǒ hái xiǎng lái.","Món gà này ngon thật, lần sau em còn muốn đến nữa."],["da","你可以拿一张菜单回去，下次想吃什么就点什么。","Nǐ kěyǐ ná yì zhāng càidān huíqu, xiàcì xiǎng chī shénme jiù diǎn shénme.","Cậu có thể cầm một tờ thực đơn về, lần sau muốn ăn gì thì gọi nấy."],["wang","不用拿菜单，用手机就能看，还可以点外卖。","Búyòng ná càidān, yòng shǒujī jiù néng kàn, hái kěyǐ diǎn wàimài.","Không cần cầm thực đơn, xem trên điện thoại là được, còn gọi giao tận nơi được nữa."],["anna","这儿也有外卖？太方便了！以前考试的时候，我只吃方便面。","Zhèr yě yǒu wàimài? Tài fāngbiàn le! Yǐqián kǎoshì de shíhou, wǒ zhǐ chī fāngbiànmiàn.","Ở đây cũng có giao đồ ăn à? Tiện quá! Trước đây hồi thi cử, em chỉ ăn mì tôm."]]}],"g":[{"t":"Câu ghép song song 又……又……","e":"又 + A + 又 + B: vừa A vừa B. A, B thường là tính từ hoặc động từ cùng loại (cùng tốt hoặc cùng xấu).","x":[["我又饿又渴。","Wǒ yòu è yòu kě."],["服务员又热情又客气。","Fúwùyuán yòu rèqíng yòu kèqi."],["这儿的菜又便宜又好吃。","Zhèr de cài yòu piányi yòu hǎochī."]]},{"t":"Đại từ nghi vấn phiếm chỉ (2)","e":"Dùng cùng một đại từ nghi vấn hai lần: 什么……什么, 哪儿……哪儿, 谁……谁 nghĩa là “muốn gì thì nấy, ở đâu thì ở đó”.","x":[["想吃什么就点什么。","Xiǎng chī shénme jiù diǎn shénme."],["你去哪儿我就去哪儿。","Nǐ qù nǎr wǒ jiù qù nǎr."],["谁先到谁买票。","Shéi xiān dào shéi mǎi piào."]]},{"t":"Đại từ nghi vấn phiếm chỉ (3)","e":"Đại từ nghi vấn + 都/也 chỉ toàn bộ, không có ngoại lệ: 什么都 (gì cũng), 谁都 (ai cũng), 哪儿都 (đâu cũng).","x":[["我什么都可以。","Wǒ shénme dōu kěyǐ."],["谁都知道这件事。","Shéi dōu zhīdào zhè jiàn shì."],["我哪儿也不想去。","Wǒ nǎr yě bù xiǎng qù."]]}],"f":[{"s":"我又饿又___！","a":"渴","o":["饱","快","热"]},{"s":"你们想吃什么就点___。","a":"什么","o":["哪儿","谁","多少"]},{"s":"请再给我们一___筷子。","a":"双","o":["张","个","碗"]},{"s":"这儿的服务员又热情又___。","a":"客气","o":["饿","简单","方便"]},{"s":"___拿菜单，用手机就能看。","a":"不用","o":["不要","别","没有"]}],"tf":[{"t":1,"s":"安娜好久没吃饺子了。","py":"Ānnà hǎojiǔ méi chī jiǎozi le.","a":"√"},{"t":2,"s":"王老师很少来这个饭店。","py":"Wáng lǎoshī hěnshǎo lái zhège fàndiàn.","a":"×"},{"t":3,"s":"这个饭店可以点外卖。","py":"Zhège fàndiàn kěyǐ diǎn wàimài.","a":"√"},{"t":3,"s":"安娜以前考试的时候常吃饺子。","py":"Ānnà yǐqián kǎoshì de shíhou cháng chī jiǎozi.","a":"×"}],"q":[{"s":"Cô Vương gọi thêm những gì?","a":"筷子、勺子和碗","o":["饺子和绿茶","菜单"]},{"s":"Vì sao phục vụ nhớ món cô Vương thích?","a":"她常来这儿","o":["她是老板","她打电话说了"]}]},{"n":3,"zh":"这个小区挺好的","py":"Zhège xiǎoqū tǐng hǎo de","vi":"Khu nhà này khá tốt","goal":["Tìm nhà, nói về môi trường sống và việc nhà.","Dùng phó từ chỉ mức độ 挺.","Dùng bổ ngữ trình độ (1): 极了, 死了, 多了.","Phân biệt 就 và 才."],"w":[["搬","bān","động từ","dọn, chuyển"],["搬家","bānjiā","động từ","chuyển nhà"],["办","bàn","động từ","làm, xử lý"],["冰箱","bīngxiāng","danh từ","tủ lạnh"],["才","cái","phó từ","mới"],["层","céng","lượng từ","tầng"],["初中","chūzhōng","danh từ","trung học cơ sở"],["打扫","dǎsǎo","động từ","quét dọn"],["灯","dēng","danh từ","đèn"],["房子","fángzi","danh từ","ngôi nhà"],["关","guān","động từ","tắt, đóng"],["花园","huāyuán","danh từ","vườn hoa"],["还","huán","động từ","trả"],["环境","huánjìng","danh từ","môi trường"],["换","huàn","động từ","đổi"],["空调","kōngtiáo","danh từ","điều hòa"],["听说","tīngshuō","động từ","nghe nói"],["挺","tǐng","phó từ","khá, rất"],["卫生间","wèishēngjiān","danh từ","nhà vệ sinh"],["洗衣机","xǐyījī","danh từ","máy giặt"],["小区","xiǎoqū","danh từ","khu dân cư"],["信用卡","xìnyòngkǎ","danh từ","thẻ tín dụng"],["需要","xūyào","động từ","cần"],["银行","yínháng","danh từ","ngân hàng"],["咱们","zánmen","đại từ","chúng ta"],["纸","zhǐ","danh từ","giấy"]],"p":[],"t":[{"s":"Tiểu Tuyết sắp vào cấp hai, cô Vương và anh Lưu tìm nhà mới.","bg":"home","l":[["wang","小雪要上初中了，学校离家挺远的，咱们换个近一点儿的房子吧。","Xiǎoxuě yào shàng chūzhōng le, xuéxiào lí jiā tǐng yuǎn de, zánmen huàn ge jìn yìdiǎnr de fángzi ba.","Tiểu Tuyết sắp lên cấp hai rồi, trường cách nhà khá xa, mình đổi sang nhà gần hơn đi anh."],["liu","好，我在网上看看。你觉得这个小区怎么样？","Hǎo, wǒ zài wǎngshang kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?","Được, anh xem trên mạng. Em thấy khu nhà này thế nào?"],["wang","环境挺好的，离地铁站也不远。","Huánjìng tǐng hǎo de, lí dìtiě zhàn yě bù yuǎn.","Môi trường khá tốt, cách ga tàu điện ngầm cũng không xa."],["liu","房子里面也不错，空调和洗衣机都是新的。","Fángzi lǐmian yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de.","Bên trong nhà cũng được, điều hòa và máy giặt đều mới."],["wang","好是好，可是我不太喜欢住一层。","Hǎo shì hǎo, kěshì wǒ bú tài xǐhuan zhù yì céng.","Tốt thì tốt, nhưng em không thích ở tầng một lắm."],["liu","一层有个小花园，我觉得还是去看看吧。","Yì céng yǒu ge xiǎo huāyuán, wǒ juéde háishi qù kànkan ba.","Tầng một có một vườn hoa nhỏ, anh thấy vẫn nên đi xem thử."]]},{"s":"Ở nhà mới, mọi thứ còn lộn xộn.","bg":"home","l":[["wang","我早上来的时候，灯还开着呢。","Wǒ zǎoshang lái de shíhou, dēng hái kāizhe ne.","Sáng nay em đến, đèn vẫn còn bật."],["liu","这几天我忙死了，走的时候可能忘了关。","Zhè jǐ tiān wǒ máng sǐ le, zǒu de shíhou kěnéng wàngle guān.","Mấy hôm nay anh bận chết đi được, lúc đi chắc quên tắt."],["wang","冰箱也不行了，这些东西放哪儿？","Bīngxiāng yě bù xíng le, zhèxiē dōngxi fàng nǎr?","Tủ lạnh cũng hỏng rồi, những đồ này để đâu đây?"],["liu","不会吧？冰箱是新的啊，我看看。","Bú huì ba? Bīngxiāng shì xīn de a, wǒ kànkan.","Không thể nào? Tủ lạnh mới mà, để anh xem."],["wang","卫生间还没打扫，衣服也没法洗。","Wèishēngjiān hái méi dǎsǎo, yīfu yě méifǎ xǐ.","Nhà vệ sinh chưa dọn, quần áo cũng không giặt được."]]},{"s":"Tính chuyện tiền chuyển nhà.","bg":"home","l":[["wang","这个月我们花的钱多极了。","Zhège yuè wǒmen huā de qián duō jíle.","Tháng này mình tiêu nhiều tiền quá."],["liu","是啊，买了冰箱，还换了空调。","Shì a, mǎile bīngxiāng, hái huànle kōngtiáo.","Đúng thế, mua tủ lạnh, còn thay điều hòa nữa."],["wang","我们星期天就能搬家吗？","Wǒmen xīngqītiān jiù néng bānjiā ma?","Chủ nhật mình chuyển nhà được không anh?"],["liu","我下午要去银行还信用卡，晚上才能回来。","Wǒ xiàwǔ yào qù yínháng huán xìnyòngkǎ, wǎnshang cái néng huílai.","Chiều nay anh phải ra ngân hàng trả thẻ tín dụng, tối mới về được."],["wang","那我下午自己去吧，需要买一些纸和灯。","Nà wǒ xiàwǔ zìjǐ qù ba, xūyào mǎi yìxiē zhǐ hé dēng.","Vậy chiều em tự đi, cần mua ít giấy và đèn."]]}],"g":[{"t":"Phó từ mức độ 挺","e":"挺 + tính từ/động từ tâm lý (+ 的): khá, rất. Hay dùng trong khẩu ngữ, nhẹ hơn 很 một chút.","x":[["学校离家挺远的。","Xuéxiào lí jiā tǐng yuǎn de."],["环境挺好的。","Huánjìng tǐng hǎo de."],["我挺喜欢这儿的。","Wǒ tǐng xǐhuan zhèr de."]]},{"t":"Bổ ngữ trình độ (1)","e":"Tính từ/động từ tâm lý + 极了 / 死了 / 多了: chỉ mức độ rất cao. 死了 thường dùng với ý không vui.","x":[["钱花得多极了。","Qián huā de duō jíle."],["我忙死了。","Wǒ máng sǐ le."],["今天比昨天好多了。","Jīntiān bǐ zuótiān hǎo duō le."]]},{"t":"Phân biệt 就 và 才","e":"就: sớm, nhanh, dễ hơn mong đợi. 才: muộn, chậm, khó hơn mong đợi.","x":[["他八点就来了。","Tā bā diǎn jiù lái le."],["他十点才来。","Tā shí diǎn cái lái."],["晚上才能回来。","Wǎnshang cái néng huílai."]]}],"f":[{"s":"环境___好的，离地铁站也不远。","a":"挺","o":["太","最","极"]},{"s":"这几天我忙___了。","a":"死","o":["极","多","完"]},{"s":"我晚上___能回来。","a":"才","o":["就","也","都"]},{"s":"我下午要去银行___信用卡。","a":"还","o":["换","办","搬"]},{"s":"卫生间还没___。","a":"打扫","o":["搬家","需要","换"]}],"tf":[{"t":1,"s":"小雪的学校离家挺远的。","py":"Xiǎoxuě de xuéxiào lí jiā tǐng yuǎn de.","a":"√"},{"t":1,"s":"王老师喜欢住一层。","py":"Wáng lǎoshī xǐhuan zhù yì céng.","a":"×"},{"t":2,"s":"冰箱是旧的。","py":"Bīngxiāng shì jiù de.","a":"×"},{"t":3,"s":"刘先生下午要去银行。","py":"Liú xiānsheng xiàwǔ yào qù yínháng.","a":"√"}],"q":[{"s":"Vì sao gia đình cô Vương muốn đổi nhà?","a":"小雪的学校离家远","o":["房子太小","环境不好"]},{"s":"Khu nhà mới có gì tốt?","a":"环境好，离地铁站不远","o":["很便宜","有大花园"]}]},{"n":4,"zh":"这家宾馆跟别的都不一样","py":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng","vi":"Khách sạn này khác hẳn những nơi khác","goal":["Nói về chuyến du lịch, nơi ở và cảnh đẹp.","Dùng mẫu “一……也/都 + 不/没……” để nhấn mạnh phủ định.","Dùng câu so sánh A 跟 B 一样 / 不一样.","Dùng mẫu 除了……（以外），……都/还/也……."],"w":[["别的","biéde","đại từ","cái khác"],["宾馆","bīnguǎn","danh từ","khách sạn"],["草原","cǎoyuán","danh từ","thảo nguyên"],["除了","chúle","giới từ","ngoài… ra"],["干净","gānjìng","tính từ","sạch sẽ"],["海","hǎi","danh từ","biển"],["欢迎","huānyíng","động từ","hoan nghênh, chào mừng"],["假期","jiàqī","danh từ","kỳ nghỉ"],["久","jiǔ","tính từ","lâu"],["刻","kè","lượng từ","khắc (15 phút)"],["马","mǎ","danh từ","ngựa"],["满意","mǎnyì","tính từ","hài lòng"],["牛","niú","danh từ","bò"],["骑","qí","động từ","cưỡi, đi (xe)"],["起飞","qǐfēi","động từ","cất cánh"],["司机","sījī","danh từ","tài xế"],["特别","tèbié","phó từ","đặc biệt"],["晚点","wǎndiǎn","động từ","trễ giờ"],["先","xiān","phó từ","trước"],["相机","xiàngjī","danh từ","máy ảnh"],["羊","yáng","danh từ","cừu, dê"],["一定","yídìng","phó từ","nhất định"],["一样","yíyàng","tính từ","giống nhau"],["以外","yǐwài","danh từ","ngoài ra"],["一直","yìzhí","phó từ","luôn, mãi"],["月亮","yuèliang","danh từ","mặt trăng"],["主意","zhǔyi","danh từ","ý kiến, ý tưởng"]],"p":[["内蒙古","Nèi Měnggǔ","","Nội Mông"]],"t":[{"s":"Kỳ nghỉ, Anna và Lê Hoa đi Nội Mông. Máy bay bị trễ.","bg":"airport","l":[["anna","飞机晚点了，现在还没起飞。","Fēijī wǎndiǎn le, xiànzài hái méi qǐfēi.","Máy bay trễ giờ rồi, bây giờ vẫn chưa cất cánh."],["hua","我们已经等了一个小时了，一点儿办法也没有。","Wǒmen yǐjīng děngle yí ge xiǎoshí le, yìdiǎnr bànfǎ yě méiyǒu.","Chúng mình đợi một tiếng rồi, chẳng có cách nào cả."],["anna","别着急，先喝点儿东西吧。","Bié zháojí, xiān hē diǎnr dōngxi ba.","Đừng sốt ruột, uống chút gì trước đã."],["hua","好主意！我一直想去草原，等多久都可以。","Hǎo zhǔyi! Wǒ yìzhí xiǎng qù cǎoyuán, děng duō jiǔ dōu kěyǐ.","Ý hay! Mình luôn muốn đi thảo nguyên, đợi bao lâu cũng được."]]},{"s":"Đến khách sạn trên thảo nguyên.","bg":"hotel","l":[["hua","这家宾馆跟别的宾馆都不一样，房间是白色的“蒙古包”。","Zhè jiā bīnguǎn gēn biéde bīnguǎn dōu bù yíyàng, fángjiān shì báisè de “Měnggǔbāo”.","Khách sạn này khác hẳn những khách sạn khác, phòng là những chiếc lều Mông Cổ màu trắng."],["anna","里面特别干净，我很满意。","Lǐmian tèbié gānjìng, wǒ hěn mǎnyì.","Bên trong cực kỳ sạch sẽ, mình rất hài lòng."],["staff","欢迎你们！明天早上八点一刻，司机带你们去骑马。","Huānyíng nǐmen! Míngtiān zǎoshang bā diǎn yí kè, sījī dài nǐmen qù qí mǎ.","Chào mừng các bạn! Tám giờ mười lăm sáng mai, tài xế sẽ đưa các bạn đi cưỡi ngựa."],["hua","太好了！除了骑马，还可以做什么？","Tài hǎo le! Chúle qí mǎ, hái kěyǐ zuò shénme?","Tuyệt quá! Ngoài cưỡi ngựa ra còn làm được gì nữa ạ?"],["staff","还可以看牛和羊，晚上还可以看月亮。","Hái kěyǐ kàn niú hé yáng, wǎnshang hái kěyǐ kàn yuèliang.","Còn có thể xem bò và cừu, buổi tối còn ngắm trăng nữa."]]},{"s":"Buổi tối, hai bạn nói chuyện về chuyến đi.","bg":"hotel","l":[["anna","草原上的月亮跟海边的月亮一样漂亮。","Cǎoyuán shang de yuèliang gēn hǎibiān de yuèliang yíyàng piàoliang.","Mặt trăng trên thảo nguyên cũng đẹp như mặt trăng ở bờ biển."],["hua","我觉得不一样，这里的天特别大。","Wǒ juéde bù yíyàng, zhèli de tiān tèbié dà.","Mình thấy khác chứ, bầu trời ở đây rộng lắm."],["anna","除了你以外，我们班的同学都没来过草原。","Chúle nǐ yǐwài, wǒmen bān de tóngxué dōu méi láiguo cǎoyuán.","Trừ cậu ra, các bạn lớp mình chưa ai đến thảo nguyên cả."],["hua","你带相机了吗？明天一定要多拍照片。","Nǐ dài xiàngjī le ma? Míngtiān yídìng yào duō pāi zhàopiàn.","Cậu mang máy ảnh chưa? Mai nhất định phải chụp nhiều ảnh."],["anna","带了，我一张照片也不想少拍。","Dài le, wǒ yì zhāng zhàopiàn yě bù xiǎng shǎo pāi.","Mang rồi, mình không muốn bỏ lỡ tấm ảnh nào."]]}],"g":[{"t":"Mẫu “一……也/都 + 不/没……”","e":"一 + lượng từ + danh từ + 也/都 + 不/没 + động từ: một… cũng không. Nhấn mạnh phủ định hoàn toàn.","x":[["一点儿办法也没有。","Yìdiǎnr bànfǎ yě méiyǒu."],["我一张照片也不想少拍。","Wǒ yì zhāng zhàopiàn yě bù xiǎng shǎo pāi."],["他一句话都没说。","Tā yí jù huà dōu méi shuō."]]},{"t":"Câu so sánh (9): 跟……一样","e":"A + 跟 + B + 一样 (+ tính từ): A giống B. Phủ định: A 跟 B 不一样.","x":[["草原上的月亮跟海边的一样漂亮。","Cǎoyuán shang de yuèliang gēn hǎibiān de yíyàng piàoliang."],["这家宾馆跟别的都不一样。","Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng."]]},{"t":"Mẫu 除了……（以外），……都/还/也……","e":"除了 A（以外），都…: trừ A ra, tất cả… (loại trừ). 除了 A（以外），还/也…: ngoài A ra còn… (bổ sung).","x":[["除了你以外，同学们都没来过。","Chúle nǐ yǐwài, tóngxuémen dōu méi láiguo."],["除了骑马，还可以看牛和羊。","Chúle qí mǎ, hái kěyǐ kàn niú hé yáng."]]}],"f":[{"s":"我们一点儿办法___没有。","a":"也","o":["还","才","就"]},{"s":"这家宾馆___别的宾馆都不一样。","a":"跟","o":["比","对","给"]},{"s":"___骑马，还可以做什么？","a":"除了","o":["以外","一直","先"]},{"s":"飞机___了，现在还没起飞。","a":"晚点","o":["起飞","迟到","欢迎"]},{"s":"房间里面特别___，我很满意。","a":"干净","o":["一样","特别","一定"]}],"tf":[{"t":1,"s":"飞机晚点了。","py":"Fēijī wǎndiǎn le.","a":"√"},{"t":2,"s":"宾馆的房间跟别的宾馆一样。","py":"Bīnguǎn de fángjiān gēn biéde bīnguǎn yíyàng.","a":"×"},{"t":2,"s":"明天早上司机带她们去骑马。","py":"Míngtiān zǎoshang sījī dài tāmen qù qí mǎ.","a":"√"},{"t":3,"s":"安娜没带相机。","py":"Ānnà méi dài xiàngjī.","a":"×"}],"q":[{"s":"Mấy giờ sáng mai tài xế đến đón?","a":"八点一刻","o":["八点半","八点"]},{"s":"Ngoài cưỡi ngựa, ở thảo nguyên còn làm gì?","a":"看牛和羊、看月亮","o":["游泳","爬山"]}]},{"n":5,"zh":"这样的照片才好看","py":"Zhèyàng de zhàopiàn cái hǎokàn","vi":"Ảnh như thế này mới đẹp","goal":["Nói về sở thích chụp ảnh, leo núi, tập thể dục.","Dùng bổ ngữ trình độ (2): 得 + 很/不得了.","Dùng lượng từ lặp lại: 个个, 张张, 天天.","Dùng câu tồn hiện (3) và câu rút gọn “……了……就……”."],"w":[["比较","bǐjiào","phó từ","tương đối, khá"],["大衣","dàyī","danh từ","áo khoác dài"],["电","diàn","danh từ","điện"],["锻炼","duànliàn","động từ","rèn luyện"],["封","fēng","lượng từ","bức, lá (thư)"],["感兴趣","gǎn xìngqù","","có hứng thú"],["干","gàn","động từ","làm"],["哈哈","hāhā","thán từ","ha ha"],["会","huì","động từ năng nguyện","sẽ"],["结束","jiéshù","động từ","kết thúc"],["难过","nánguò","tính từ","buồn"],["难看","nánkàn","tính từ","xấu"],["爬","pá","động từ","leo, bò"],["拍照","pāizhào","động từ","chụp ảnh"],["山","shān","danh từ","núi"],["收到","shōudào","động từ","nhận được"],["树","shù","danh từ","cây"],["水平","shuǐpíng","danh từ","trình độ"],["太阳","tàiyáng","danh từ","mặt trời"],["鞋","xié","danh từ","giày"],["兴趣","xìngqù","danh từ","hứng thú"],["音乐","yīnyuè","danh từ","âm nhạc"],["邮件","yóujiàn","danh từ","thư, email"],["照","zhào","động từ","chụp (ảnh)"],["照相","zhàoxiàng","động từ","chụp ảnh"],["终于","zhōngyú","phó từ","cuối cùng"],["总是","zǒngshì","phó từ","luôn luôn"]],"p":[],"t":[{"s":"Trời nắng sau mấy ngày âm u, Lê Hoa rủ Minh đi leo núi.","bg":"campus","l":[["hua","阴了一个星期，今天终于出太阳了。","Yīnle yí ge xīngqī, jīntiān zhōngyú chū tàiyáng le.","Âm u cả tuần, hôm nay cuối cùng cũng có nắng."],["ming","天气好得很！咱们去爬山吧？","Tiānqì hǎo de hěn! Zánmen qù páshān ba?","Thời tiết đẹp quá! Chúng mình đi leo núi đi?"],["hua","好主意！又可以锻炼，又可以拍照。","Hǎo zhǔyi! Yòu kěyǐ duànliàn, yòu kěyǐ pāizhào.","Ý hay! Vừa rèn luyện sức khỏe, vừa chụp ảnh được."],["ming","我带些水和吃的。咱们现在就走？","Wǒ dài xiē shuǐ hé chī de. Zánmen xiànzài jiù zǒu?","Mình mang ít nước và đồ ăn. Chúng mình đi luôn nhé?"],["hua","我回去换双鞋，再拿件大衣就走。","Wǒ huíqu huàn shuāng xié, zài ná jiàn dàyī jiù zǒu.","Mình về thay đôi giày, lấy thêm cái áo khoác rồi đi."]]},{"s":"Xem ảnh trong điện thoại.","bg":"cafe","l":[["da","这些照片是谁给你照的？张张都很好看。","Zhèxiē zhàopiàn shì shéi gěi nǐ zhào de? Zhāngzhāng dōu hěn hǎokàn.","Những ảnh này ai chụp cho cậu thế? Tấm nào cũng đẹp."],["hua","是安娜。她对照相特别感兴趣，总是给我拍照。","Shì Ānnà. Tā duì zhàoxiàng tèbié gǎn xìngqù, zǒngshì gěi wǒ pāizhào.","Là Anna. Cậu ấy rất thích chụp ảnh, lúc nào cũng chụp cho mình."],["da","她拍照的水平比较高。","Tā pāizhào de shuǐpíng bǐjiào gāo.","Trình độ chụp ảnh của cậu ấy khá cao."],["hua","我最喜欢这张，树上站着一只小鸟。","Wǒ zuì xǐhuan zhè zhāng, shù shang zhànzhe yì zhī xiǎoniǎo.","Mình thích nhất tấm này, trên cây có một chú chim nhỏ đậu."]]},{"s":"Trên núi, Anna chụp ảnh cho Lê Hoa.","bg":"park","l":[["anna","这儿没有太阳，我们去那边照吧。","Zhèr méiyǒu tàiyáng, wǒmen qù nàbian zhào ba.","Ở đây không có nắng, chúng mình sang bên kia chụp đi."],["hua","好。我站在这几棵树中间，怎么样？","Hǎo. Wǒ zhàn zài zhè jǐ kē shù zhōngjiān, zěnmeyàng?","Được. Mình đứng giữa mấy cái cây này, thế nào?"],["anna","不错。不用看我，想干什么就干什么，这样的照片才好看。","Búcuò. Búyòng kàn wǒ, xiǎng gàn shénme jiù gàn shénme, zhèyàng de zhàopiàn cái hǎokàn.","Được đấy. Không cần nhìn mình, muốn làm gì thì làm, ảnh như vậy mới đẹp."],["hua","哈哈，那我看那只小鸟。","Hāhā, nà wǒ kàn nà zhī xiǎoniǎo.","Ha ha, vậy mình nhìn chú chim kia."],["anna","哎呀，手机没电了！","Āiyā, shǒujī méi diàn le!","Ôi, điện thoại hết pin rồi!"]]}],"g":[{"t":"Bổ ngữ trình độ (2)","e":"Tính từ + 得 + 很 / 不得了 / 要命: mức độ rất cao.","x":[["天气好得很！","Tiānqì hǎo de hěn!"],["我高兴得不得了。","Wǒ gāoxìng de bùdéliǎo."],["今天热得很。","Jīntiān rè de hěn."]]},{"t":"Lặp lượng từ","e":"Lượng từ lặp lại (个个, 张张, 天天, 人人) nghĩa là “mỗi…, tất cả… đều”. Thường có 都 phía sau.","x":[["张张都很好看。","Zhāngzhāng dōu hěn hǎokàn."],["他天天锻炼。","Tā tiāntiān duànliàn."],["同学们个个都很高兴。","Tóngxuémen gègè dōu hěn gāoxìng."]]},{"t":"Câu tồn hiện (3)","e":"Nơi chốn + động từ + 着 / 了 + số lượng + người/vật: ở đâu có ai/cái gì xuất hiện, tồn tại.","x":[["树上站着一只小鸟。","Shù shang zhànzhe yì zhī xiǎoniǎo."],["前面来了一个人。","Qiánmian lái le yí ge rén."]]},{"t":"Câu rút gọn “……了……就……”","e":"Động từ 1 + 了 + … + 就 + động từ 2: làm xong việc này thì làm việc kia ngay.","x":[["我换了鞋就走。","Wǒ huànle xié jiù zǒu."],["下了课就去吃饭。","Xiàle kè jiù qù chī fàn."]]}],"f":[{"s":"天气好___很！","a":"得","o":["的","地","了"]},{"s":"这些照片___都很好看。","a":"张张","o":["个个","天天","人人"]},{"s":"她对照相特别感___。","a":"兴趣","o":["意思","水平","音乐"]},{"s":"阴了一个星期，今天___出太阳了。","a":"终于","o":["总是","一直","比较"]},{"s":"手机没___了！","a":"电","o":["钱","水","事"]}],"tf":[{"t":1,"s":"今天出太阳了。","py":"Jīntiān chū tàiyáng le.","a":"√"},{"t":1,"s":"阮明不想去爬山。","py":"Ruǎn Míng bù xiǎng qù páshān.","a":"×"},{"t":2,"s":"黎花的照片是大中拍的。","py":"Lí Huā de zhàopiàn shì Dàzhōng pāi de.","a":"×"},{"t":3,"s":"最后手机没电了。","py":"Zuìhòu shǒujī méi diàn le.","a":"√"}],"q":[{"s":"Lê Hoa về nhà lấy gì?","a":"鞋和大衣","o":["水和吃的","相机"]},{"s":"Anna nói ảnh thế nào mới đẹp?","a":"想干什么就干什么","o":["一直看镜头","站在太阳下"]}]},{"n":6,"zh":"高铁上还可以点外卖","py":"Gāotiě shang hái kěyǐ diǎn wàimài","vi":"Trên tàu cao tốc còn gọi được đồ ăn","goal":["Mua vé và đi tàu cao tốc ở Trung Quốc.","Dùng mẫu “该……了” để nói đến lúc làm gì.","Dùng câu giả thiết 如果……，就…….","Dùng cụm cố định 越来越."],"w":[["安静","ānjìng","tính từ","yên tĩnh"],["必须","bìxū","phó từ","bắt buộc phải"],["常用","cháng yòng","","hay dùng, thường dùng"],["迟到","chídào","động từ","đến muộn"],["充电宝","chōngdiànbǎo","danh từ","sạc dự phòng"],["打算","dǎsuàn","động từ","định, dự định"],["电梯","diàntī","danh từ","thang máy"],["耳机","ěrjī","danh từ","tai nghe"],["放假","fàngjià","động từ","nghỉ lễ, được nghỉ"],["分开","fēnkāi","động từ","tách ra"],["该","gāi","động từ năng nguyện","nên, đến lúc"],["高铁","gāotiě","danh từ","tàu cao tốc"],["红绿灯","hóng-lǜdēng","danh từ","đèn giao thông"],["后来","hòulái","danh từ","sau đó, về sau"],["急","jí","tính từ","gấp, vội"],["检查","jiǎnchá","động từ","kiểm tra"],["检票","jiǎnpiào","động từ","soát vé"],["路口","lùkǒu","danh từ","ngã tư, giao lộ"],["如果","rúguǒ","liên từ","nếu"],["沙发","shāfā","danh từ","ghế sô pha"],["刷","shuā","động từ","quẹt, quét (thẻ)"],["小心","xiǎoxīn","động từ","cẩn thận"],["行","xíng","tính từ","được"],["选择","xuǎnzé","động từ","lựa chọn"],["以前","yǐqián","danh từ","trước đây"],["越","yuè","phó từ","càng"]],"p":[["上海","Shànghǎi","","Thượng Hải"],["北京南站","Běijīng Nán Zhàn","","ga Bắc Kinh Nam"]],"t":[{"s":"Sắp nghỉ lễ, Anna và Đại Trung bàn chuyện đi Thượng Hải.","bg":"campus","l":[["da","安娜，快放假了，我们该买去上海的票了。你打算怎么去？","Ānnà, kuài fàngjià le, wǒmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuan zěnme qù?","Anna, sắp nghỉ lễ rồi, chúng mình nên mua vé đi Thượng Hải thôi. Cậu định đi bằng gì?"],["anna","我以前没坐过高铁，我们坐高铁吧？","Wǒ yǐqián méi zuòguo gāotiě, wǒmen zuò gāotiě ba?","Trước đây mình chưa đi tàu cao tốc bao giờ, chúng mình đi tàu cao tốc nhé?"],["da","行。从北京到上海的高铁很多，非常方便。","Xíng. Cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.","Được. Từ Bắc Kinh đi Thượng Hải có nhiều chuyến tàu cao tốc, rất tiện."],["anna","太好了！票怎么买？","Tài hǎo le! Piào zěnme mǎi?","Tuyệt quá! Mua vé thế nào?"],["da","用手机买就行，把护照给我，我帮你买。","Yòng shǒujī mǎi jiù xíng, bǎ hùzhào gěi wǒ, wǒ bāng nǐ mǎi.","Mua bằng điện thoại là được, đưa hộ chiếu cho mình, mình mua giúp cậu."]]},{"s":"Trên taxi đến ga Bắc Kinh Nam.","bg":"street","l":[["siji","过了前面那个路口，就到北京南站了。","Guòle qiánmian nàge lùkǒu, jiù dào Běijīng Nán Zhàn le.","Qua ngã tư phía trước là đến ga Bắc Kinh Nam."],["da","师傅，我们有点儿急，九点的车，会不会迟到？","Shīfu, wǒmen yǒudiǎnr jí, jiǔ diǎn de chē, huì bu huì chídào?","Bác tài ơi, chúng cháu hơi gấp, tàu chín giờ, liệu có muộn không ạ?"],["siji","别急，如果红绿灯不多，二十分钟就能到。","Bié jí, rúguǒ hóng-lǜdēng bù duō, èrshí fēnzhōng jiù néng dào.","Đừng vội, nếu không nhiều đèn đỏ thì hai mươi phút là đến."],["anna","我的手机快没电了，你有充电宝吗？","Wǒ de shǒujī kuài méi diàn le, nǐ yǒu chōngdiànbǎo ma?","Điện thoại mình sắp hết pin rồi, cậu có sạc dự phòng không?"],["da","有，这些常用的东西我都放在包里。","Yǒu, zhèxiē cháng yòng de dōngxi wǒ dōu fàng zài bāo li.","Có, những đồ hay dùng này mình đều để trong túi."]]},{"s":"Trong ga tàu cao tốc.","bg":"street","l":[["anna","前面的人越来越多了。","Qiánmian de rén yuè lái yuè duō le.","Người phía trước càng lúc càng đông."],["da","对，我们马上要进站了，别分开，小心点儿。","Duì, wǒmen mǎshàng yào jìnzhàn le, bié fēnkāi, xiǎoxīn diǎnr.","Ừ, chúng mình sắp vào ga rồi, đừng tách nhau ra, cẩn thận nhé."],["anna","检票的地方在哪儿？","Jiǎnpiào de dìfang zài nǎr?","Chỗ soát vé ở đâu?"],["da","在二层，我们坐电梯上去。不用纸票，刷护照就可以了。","Zài èr céng, wǒmen zuò diàntī shàngqu. Búyòng zhǐ piào, shuā hùzhào jiù kěyǐ le.","Ở tầng hai, chúng mình đi thang máy lên. Không cần vé giấy, quẹt hộ chiếu là được."],["anna","听说高铁上还可以点外卖，又安静又舒服！","Tīngshuō gāotiě shang hái kěyǐ diǎn wàimài, yòu ānjìng yòu shūfu!","Nghe nói trên tàu cao tốc còn gọi được đồ ăn, vừa yên tĩnh vừa thoải mái!"]]}],"g":[{"t":"Mẫu “该……了”","e":"(Chủ ngữ) + 该 + động từ + 了: đến lúc phải làm gì rồi.","x":[["我们该买票了。","Wǒmen gāi mǎipiào le."],["十二点了，该睡觉了。","Shí'èr diǎn le, gāi shuìjiào le."],["该你了！","Gāi nǐ le!"]]},{"t":"Câu giả thiết 如果……，就……","e":"如果 + điều kiện giả định，(chủ ngữ) + 就 + kết quả: nếu… thì…","x":[["如果红绿灯不多，二十分钟就能到。","Rúguǒ hóng-lǜdēng bù duō, èrshí fēnzhōng jiù néng dào."],["如果明天下雨，我们就不去了。","Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le."]]},{"t":"Cụm cố định 越来越","e":"越来越 + tính từ/động từ tâm lý: ngày càng…","x":[["前面的人越来越多了。","Qiánmian de rén yuè lái yuè duō le."],["天气越来越冷。","Tiānqì yuè lái yuè lěng."],["我越来越喜欢汉语了。","Wǒ yuè lái yuè xǐhuan Hànyǔ le."]]}],"f":[{"s":"快放假了，我们___买票了。","a":"该","o":["会","能","要"]},{"s":"___红绿灯不多，二十分钟就能到。","a":"如果","o":["因为","虽然","但是"]},{"s":"前面的人___多了。","a":"越来越","o":["一直","比较","特别"]},{"s":"不用纸票，___护照就可以了。","a":"刷","o":["用","带","看"]},{"s":"我们马上要进站了，别___。","a":"分开","o":["迟到","小心","检查"]}],"tf":[{"t":1,"s":"安娜以前坐过高铁。","py":"Ānnà yǐqián zuòguo gāotiě.","a":"×"},{"t":2,"s":"他们坐的是九点的车。","py":"Tāmen zuò de shì jiǔ diǎn de chē.","a":"√"},{"t":3,"s":"检票的地方在一层。","py":"Jiǎnpiào de dìfang zài yì céng.","a":"×"},{"t":3,"s":"进站要用纸票。","py":"Jìnzhàn yào yòng zhǐ piào.","a":"×"}],"q":[{"s":"Mua vé tàu cao tốc bằng cách nào?","a":"用手机买","o":["去车站买","打电话买"]},{"s":"Chỗ soát vé ở đâu?","a":"二层","o":["一层","门口"]}]},{"n":7,"zh":"那条裙子比短裤更好看","py":"Nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn","vi":"Chiếc váy kia đẹp hơn quần soóc","goal":["Mua sắm quần áo, hoa quả, xe đạp; so sánh hàng hóa.","Dùng câu so sánh A 比 B 更/还 + tính từ.","Dùng bổ ngữ trình độ (3): ……极了.","Dùng câu tăng tiến 不但……，而且……."],"w":[["矮","ǎi","tính từ","thấp"],["冰","bīng","danh từ","đá, băng"],["不但","búdàn","liên từ","không những"],["大小","dàxiǎo","danh từ","kích cỡ"],["短裤","duǎnkù","danh từ","quần soóc"],["而且","érqiě","liên từ","mà còn"],["更","gèng","phó từ","càng, hơn"],["公斤","gōngjīn","lượng từ","ki-lô-gam"],["合适","héshì","tính từ","vừa vặn, phù hợp"],["黄色","huángsè","danh từ","màu vàng"],["极","jí","phó từ","cực kỳ"],["结婚","jiéhūn","động từ","kết hôn"],["斤","jīn","lượng từ","cân (0,5 kg)"],["旧","jiù","tính từ","cũ"],["决定","juédìng","động từ","quyết định"],["开机","kāijī","động từ","mở máy"],["辆","liàng","lượng từ","chiếc (xe)"],["毛","máo","lượng từ","hào (1/10 tệ)"],["裙子","qúnzi","danh từ","váy"],["声","shēng","danh từ","tiếng"],["试","shì","động từ","thử"],["甜","tián","tính từ","ngọt"],["西瓜","xīguā","danh từ","dưa hấu"],["香蕉","xiāngjiāo","danh từ","chuối"],["新鲜","xīnxiān","tính từ","tươi"],["一共","yígòng","phó từ","tổng cộng"],["自行车","zìxíngchē","danh từ","xe đạp"]],"p":[],"t":[{"s":"Ở cửa hàng quần áo, Lê Hoa và Anna chọn đồ.","bg":"shop","l":[["hua","我穿这条黄色的短裤怎么样？","Wǒ chuān zhè tiáo huángsè de duǎnkù zěnmeyàng?","Mình mặc chiếc quần soóc màu vàng này thế nào?"],["anna","不错，不过那条裙子比短裤更好看。","Búcuò, búguò nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn.","Được đấy, nhưng chiếc váy kia đẹp hơn quần soóc."],["hua","我试试……大小挺合适的，就是有点儿长。","Wǒ shìshi…… dàxiǎo tǐng héshì de, jiùshì yǒudiǎnr cháng.","Để mình thử… Cỡ khá vừa, chỉ hơi dài."],["anna","你不矮，穿裙子好看极了。","Nǐ bù ǎi, chuān qúnzi hǎokàn jíle.","Cậu không thấp, mặc váy đẹp lắm."],["hua","好，我决定了，就买这条裙子！","Hǎo, wǒ juédìng le, jiù mǎi zhè tiáo qúnzi!","Được, mình quyết định rồi, mua chiếc váy này!"]]},{"s":"Ở sạp hoa quả.","bg":"market","l":[["seller","西瓜又甜又新鲜，三块五毛钱一斤。","Xīguā yòu tián yòu xīnxiān, sān kuài wǔ máo qián yì jīn.","Dưa hấu vừa ngọt vừa tươi, ba tệ rưỡi một cân."],["hua","给我拿一个吧。香蕉怎么卖？","Gěi wǒ ná yí ge ba. Xiāngjiāo zěnme mài?","Lấy cho cháu một quả ạ. Chuối bán thế nào ạ?"],["seller","五块一斤。今天的香蕉比昨天的还好。","Wǔ kuài yì jīn. Jīntiān de xiāngjiāo bǐ zuótiān de hái hǎo.","Năm tệ một cân. Chuối hôm nay còn ngon hơn hôm qua."],["hua","再要两斤香蕉。一共多少钱？","Zài yào liǎng jīn xiāngjiāo. Yígòng duōshao qián?","Lấy thêm hai cân chuối. Tổng cộng bao nhiêu tiền ạ?"],["seller","西瓜十公斤，一共七十八块。","Xīguā shí gōngjīn, yígòng qīshíbā kuài.","Dưa hấu 10 cân, tổng cộng 78 tệ."]]},{"s":"Minh muốn mua xe đạp mới.","bg":"campus","l":[["ming","我的自行车太旧了，我想买一辆新的。","Wǒ de zìxíngchē tài jiù le, wǒ xiǎng mǎi yí liàng xīn de.","Xe đạp của mình cũ quá rồi, mình muốn mua một chiếc mới."],["da","我哥哥结婚以后，不但买了车，而且还有一辆新自行车，他不骑了。","Wǒ gēge jiéhūn yǐhòu, búdàn mǎile chē, érqiě hái yǒu yí liàng xīn zìxíngchē, tā bù qí le.","Anh mình sau khi kết hôn không những mua ô tô, mà còn có một chiếc xe đạp mới, anh ấy không đi nữa."],["ming","真的吗？我可以试试吗？","Zhēn de ma? Wǒ kěyǐ shìshi ma?","Thật à? Mình đi thử được không?"],["da","当然可以。我给他打个电话……哎，他没开机。","Dāngrán kěyǐ. Wǒ gěi tā dǎ ge diànhuà…… āi, tā méi kāijī.","Tất nhiên rồi. Để mình gọi cho anh ấy… Ơ, anh ấy chưa mở máy."]]}],"g":[{"t":"Câu so sánh (10): 比……更/还","e":"A + 比 + B + 更/还 + tính từ: A còn… hơn B. Dùng khi B cũng đã có tính chất đó.","x":[["那条裙子比短裤更好看。","Nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn."],["今天的香蕉比昨天的还好。","Jīntiān de xiāngjiāo bǐ zuótiān de hái hǎo."]]},{"t":"Bổ ngữ trình độ (3): 极了","e":"Tính từ + 极了: cực kỳ, vô cùng.","x":[["你穿裙子好看极了。","Nǐ chuān qúnzi hǎokàn jíle."],["这个西瓜甜极了。","Zhège xīguā tián jíle."]]},{"t":"Câu tăng tiến 不但……，而且……","e":"不但 A，而且 B: không những A mà còn B. Cùng chủ ngữ thì 不但 đứng sau chủ ngữ.","x":[["他不但买了车，而且还有一辆自行车。","Tā búdàn mǎile chē, érqiě hái yǒu yí liàng zìxíngchē."],["这个西瓜不但大，而且很甜。","Zhège xīguā búdàn dà, érqiě hěn tián."]]}],"f":[{"s":"那条裙子比短裤___好看。","a":"更","o":["很","太","最"]},{"s":"你穿裙子好看___了。","a":"极","o":["死","多","太"]},{"s":"他___买了车，而且还有自行车。","a":"不但","o":["因为","虽然","如果"]},{"s":"再要两斤香蕉。___多少钱？","a":"一共","o":["一起","一定","一样"]},{"s":"我的自行车太___了，我想买一辆新的。","a":"旧","o":["新","甜","矮"]}],"tf":[{"t":1,"s":"黎花最后买了短裤。","py":"Lí Huā zuìhòu mǎile duǎnkù.","a":"×"},{"t":2,"s":"今天的香蕉比昨天的还好。","py":"Jīntiān de xiāngjiāo bǐ zuótiān de hái hǎo.","a":"√"},{"t":2,"s":"西瓜五块一斤。","py":"Xīguā wǔ kuài yì jīn.","a":"×"},{"t":3,"s":"大中的哥哥没开机。","py":"Dàzhōng de gēge méi kāijī.","a":"√"}],"q":[{"s":"Dưa hấu bao nhiêu tiền một cân?","a":"三块五","o":["五块","三块"]},{"s":"Vì sao Minh muốn mua xe đạp mới?","a":"他的自行车太旧了","o":["他的自行车丢了","他没有自行车"]}]},{"n":8,"zh":"今天我出院了","py":"Jīntiān wǒ chūyuàn le","vi":"Hôm nay tôi ra viện","goal":["Nói về sức khỏe, bệnh tật, đi bệnh viện.","Dùng nghĩa mở rộng của bổ ngữ xu hướng (1): 起来, 下来, 下去.","Dùng từ ly hợp và bổ ngữ thời lượng (2).","Dùng mẫu “……以前/以后/前/后”."],"w":[["病人","bìngrén","danh từ","bệnh nhân"],["差不多","chàbuduō","phó từ","gần như, xấp xỉ"],["常","cháng","phó từ","thường"],["出院","chūyuàn","động từ","ra viện"],["担心","dānxīn","động từ","lo lắng"],["得","děi","động từ năng nguyện","phải"],["低","dī","tính từ","thấp"],["耳朵","ěrduo","danh từ","tai"],["发烧","fāshāo","động từ","sốt"],["方法","fāngfǎ","danh từ","phương pháp"],["感冒","gǎnmào","động từ","cảm cúm"],["关心","guānxīn","động từ","quan tâm"],["健康","jiànkāng","tính từ","khỏe mạnh"],["开","kāi","động từ","kê (đơn thuốc)"],["开心","kāixīn","tính từ","vui vẻ"],["胖","pàng","tính từ","béo"],["其他","qítā","đại từ","khác"],["体育馆","tǐyùguǎn","danh từ","nhà thi đấu"],["突然","tūrán","tính từ","đột nhiên"],["腿","tuǐ","danh từ","chân"],["习惯","xíguàn","danh từ","thói quen"],["心里","xīnli","danh từ","trong lòng"],["以后","yǐhòu","danh từ","sau này, sau khi"],["羽毛球","yǔmáoqiú","danh từ","cầu lông"],["种","zhǒng","lượng từ","loại"],["住院","zhùyuàn","động từ","nằm viện"],["注意","zhùyì","động từ","chú ý"],["最近","zuìjìn","danh từ","gần đây"]],"p":[],"t":[{"s":"Ở nhà thi đấu, Minh gặp Đại Trung.","bg":"campus","l":[["ming","大中，最近我常在体育馆看见你。","Dàzhōng, zuìjìn wǒ cháng zài tǐyùguǎn kànjiàn nǐ.","Đại Trung, dạo này mình hay thấy cậu ở nhà thi đấu."],["da","我每天下午来跑一个小时步。","Wǒ měi tiān xiàwǔ lái pǎo yí ge xiǎoshí bù.","Chiều nào mình cũng đến chạy bộ một tiếng."],["ming","这是个好习惯。","Zhè shì ge hǎo xíguàn.","Đó là thói quen tốt."],["da","今年我胖了十多斤，不能再胖下去了，不健康。","Jīnnián wǒ pàngle shí duō jīn, bù néng zài pàng xiaqu le, bú jiànkāng.","Năm nay mình béo lên hơn 10 cân, không thể béo thêm nữa, không tốt cho sức khỏe."],["ming","下了课我常打羽毛球，你也一起来吧，我教你。","Xiàle kè wǒ cháng dǎ yǔmáoqiú, nǐ yě yìqǐ lái ba, wǒ jiāo nǐ.","Tan học mình hay chơi cầu lông, cậu cũng chơi cùng đi, mình dạy cậu."]]},{"s":"Đại Trung bị sốt sau khi đi bơi.","bg":"campus","l":[["anna","你怎么了？看起来不太好。","Nǐ zěnme le? Kàn qilai bú tài hǎo.","Cậu sao thế? Trông không được khỏe lắm."],["da","昨天游泳以后，耳朵就疼起来了。","Zuótiān yóuyǒng yǐhòu, ěrduo jiù téng qilai le.","Hôm qua đi bơi về là tai bắt đầu đau."],["anna","可能是感冒了，你发烧吗？","Kěnéng shì gǎnmào le, nǐ fāshāo ma?","Có thể bị cảm rồi, cậu có sốt không?"],["da","有点儿发烧，我先回家睡一会儿觉。","Yǒudiǎnr fāshāo, wǒ xiān huí jiā shuì yíhuìr jiào.","Hơi sốt, mình về nhà ngủ một lát trước đã."],["anna","好，如果下午还发烧，你得去医院看看。","Hǎo, rúguǒ xiàwǔ hái fāshāo, nǐ děi qù yīyuàn kànkan.","Được, nếu chiều vẫn còn sốt thì cậu phải đi bệnh viện khám đấy."]]},{"s":"Đại Trung đi khám và nằm viện vài ngày rồi ra viện.","bg":"hospital","l":[["doc","你的腿疼了多长时间了？","Nǐ de tuǐ téngle duō cháng shíjiān le?","Chân cháu đau bao lâu rồi?"],["da","差不多两个星期了，前天突然疼得走不了路。","Chàbuduō liǎng ge xīngqī le, qiántiān tūrán téng de zǒu bu liǎo lù.","Gần hai tuần rồi ạ, hôm kia đột nhiên đau đến mức không đi được."],["doc","你得住几天院。注意休息，我给你开点儿药。","Nǐ děi zhù jǐ tiān yuàn. Zhùyì xiūxi, wǒ gěi nǐ kāi diǎnr yào.","Cháu phải nằm viện mấy hôm. Chú ý nghỉ ngơi, tôi kê cho cháu ít thuốc."],["da","好的，谢谢医生。","Hǎo de, xièxie yīshēng.","Vâng, cháu cảm ơn bác sĩ."],["doc","你身体不错，住院以后很快就能好起来，别担心。","Nǐ shēntǐ búcuò, zhùyuàn yǐhòu hěn kuài jiù néng hǎo qilai, bié dānxīn.","Sức khỏe cháu tốt, nằm viện ít hôm là khỏe lại nhanh thôi, đừng lo."]]}],"g":[{"t":"Nghĩa mở rộng của bổ ngữ xu hướng (1)","e":"起来: bắt đầu và tiếp tục (疼起来, 好起来). 下去: tiếp tục làm (胖下去, 说下去). 下来: từ động sang tĩnh (停下来).","x":[["耳朵就疼起来了。","Ěrduo jiù téng qilai le."],["不能再胖下去了。","Bù néng zài pàng xiaqu le."],["很快就能好起来。","Hěn kuài jiù néng hǎo qilai."]]},{"t":"Từ ly hợp","e":"Một số động từ có thể tách đôi để chen thành phần vào giữa: 跑步 → 跑一个小时步, 睡觉 → 睡一会儿觉, 住院 → 住几天院.","x":[["我每天跑一个小时步。","Wǒ měi tiān pǎo yí ge xiǎoshí bù."],["我先睡一会儿觉。","Wǒ xiān shuì yíhuìr jiào."],["你得住几天院。","Nǐ děi zhù jǐ tiān yuàn."]]},{"t":"Bổ ngữ thời lượng (2)","e":"Động từ + 了 + thời gian + 了: hành động kéo dài bao lâu và vẫn còn tiếp tục.","x":[["你的腿疼了多长时间了？","Nǐ de tuǐ téngle duō cháng shíjiān le?"],["他学汉语学了两年了。","Tā xué Hànyǔ xuéle liǎng nián le."]]},{"t":"Mẫu “……以前/以后/前/后”","e":"Động từ/cụm từ/thời gian + 以前/以后 (hoặc 前/后): trước khi…, sau khi…","x":[["游泳以后","Yóuyǒng yǐhòu"],["下了课以后","Xiàle kè yǐhòu"],["睡觉前","Shuìjiào qián"]]}],"f":[{"s":"昨天游泳以后，耳朵就疼___了。","a":"起来","o":["下去","下来","上来"]},{"s":"不能再胖___了。","a":"下去","o":["起来","上来","出来"]},{"s":"我先回家睡一会儿___。","a":"觉","o":["步","院","课"]},{"s":"你___去医院看看。","a":"得","o":["的","地","着"]},{"s":"别___，你很快就能好起来。","a":"担心","o":["关心","注意","开心"]}],"tf":[{"t":1,"s":"大中每天下午来跑步。","py":"Dàzhōng měi tiān xiàwǔ lái pǎobù.","a":"√"},{"t":1,"s":"大中今年瘦了十多斤。","py":"Dàzhōng jīnnián shòu le shíduō jīn.","a":"×"},{"t":2,"s":"大中有点儿发烧。","py":"Dàzhōng yǒudiǎnr fāshāo.","a":"√"},{"t":3,"s":"大中的腿疼了两个月了。","py":"Dàzhōng de tuǐténg le liǎng ge yuè le.","a":"×"}],"q":[{"s":"Đại Trung chạy bộ bao lâu mỗi ngày?","a":"一个小时","o":["半个小时","两个小时"]},{"s":"Bác sĩ dặn Đại Trung gì?","a":"注意休息","o":["多运动","马上出院"]}]},{"n":9,"zh":"打不好没关系","py":"Dǎ bu hǎo méi guānxi","vi":"Đánh không giỏi cũng không sao","goal":["Nói về thể thao và thi đấu.","Dùng câu mục đích 为了…….","Dùng bổ ngữ khả năng: 打得好 / 打不好.","Dùng mẫu 越 A 越 B."],"w":[["比赛","bǐsài","danh từ","trận đấu"],["参加","cānjiā","động từ","tham gia"],["成绩","chéngjì","danh từ","thành tích, điểm"],["得到","dédào","động từ","đạt được"],["得分","défēn","động từ","ghi điểm"],["好多","hǎoduō","số từ","rất nhiều"],["回","huí","lượng từ","lần"],["几乎","jīhū","phó từ","gần như"],["紧张","jǐnzhāng","tính từ","căng thẳng"],["卡","kǎ","danh từ","thẻ"],["练","liàn","động từ","luyện"],["练习","liànxí","động từ","luyện tập"],["男生","nánshēng","danh từ","nam sinh"],["啤酒","píjiǔ","danh từ","bia"],["球场","qiúchǎng","danh từ","sân bóng"],["世界","shìjiè","danh từ","thế giới"],["受到","shòudào","động từ","nhận được, bị"],["体育","tǐyù","danh từ","thể dục, thể thao"],["网球","wǎngqiú","danh từ","quần vợt"],["为了","wèile","giới từ","để, vì"],["校园","xiàoyuán","danh từ","sân trường"],["影响","yǐngxiǎng","động từ","ảnh hưởng"],["运动会","yùndònghuì","danh từ","hội thao"],["运动员","yùndòngyuán","danh từ","vận động viên"],["只是","zhǐshì","phó từ","chỉ là"],["主要","zhǔyào","tính từ","chủ yếu"]],"p":[["奥运会","Àoyùnhuì","","Thế vận hội Olympic"]],"t":[{"s":"Trường sắp tổ chức hội thao.","bg":"campus","l":[["da","下个月学校有运动会，你参加吗？","Xià ge yuè xuéxiào yǒu yùndònghuì, nǐ cānjiā ma?","Tháng sau trường có hội thao, cậu tham gia không?"],["ming","我想参加网球比赛，可是我打得不太好。","Wǒ xiǎng cānjiā wǎngqiú bǐsài, kěshì wǒ dǎ de bú tài hǎo.","Mình muốn thi quần vợt, nhưng mình đánh không giỏi lắm."],["da","打不好没关系，主要是参加。","Dǎ bu hǎo méi guānxi, zhǔyào shì cānjiā.","Đánh không giỏi cũng không sao, chủ yếu là tham gia."],["ming","为了这次比赛，我每天下午都去球场练习。","Wèile zhè cì bǐsài, wǒ měi tiān xiàwǔ dōu qù qiúchǎng liànxí.","Để chuẩn bị cho cuộc thi này, chiều nào mình cũng ra sân tập."],["da","我也去！我们一起练。","Wǒ yě qù! Wǒmen yìqǐ liàn.","Mình cũng đi! Chúng mình cùng tập."]]},{"s":"Ngày thi đấu, Minh rất căng thẳng.","bg":"campus","l":[["ming","这么多人看，我紧张得几乎打不了球了。","Zhème duō rén kàn, wǒ jǐnzhāng de jīhū dǎ bu liǎo qiú le.","Nhiều người xem quá, mình căng thẳng đến mức gần như không đánh được."],["hua","别紧张，就像平时练习一样。","Bié jǐnzhāng, jiù xiàng píngshí liànxí yíyàng.","Đừng căng thẳng, cứ như lúc tập bình thường thôi."],["ming","我越想越紧张。","Wǒ yuè xiǎng yuè jǐnzhāng.","Mình càng nghĩ càng căng thẳng."],["hua","你看，你已经得分了！打得真好！","Nǐ kàn, nǐ yǐjīng défēn le! Dǎ de zhēn hǎo!","Cậu xem, cậu ghi điểm rồi kìa! Đánh hay quá!"],["ming","谢谢！听到大家加油，我就不紧张了。","Xièxie! Tīngdào dàjiā jiāyóu, wǒ jiù bù jǐnzhāng le.","Cảm ơn cậu! Nghe mọi người cổ vũ, mình hết căng thẳng rồi."]]},{"s":"Xem Thế vận hội trên ti vi ở nhà.","bg":"home","l":[["liu","今天晚上有奥运会的网球比赛，咱们一起看吧。","Jīntiān wǎnshang yǒu Àoyùnhuì de wǎngqiú bǐsài, zánmen yìqǐ kàn ba.","Tối nay có trận quần vợt Olympic, cả nhà cùng xem nhé."],["xue","好！这个运动员是世界第一，受到好多人喜爱。","Hǎo! Zhège yùndòngyuán shì shìjiè dì-yī, shòudào hǎoduō rén xǐ'ài.","Vâng! Vận động viên này là số một thế giới, rất nhiều người yêu thích."],["liu","他的成绩越来越好了。小雪，你喜欢体育吗？","Tā de chéngjì yuè lái yuè hǎo le. Xiǎoxuě, nǐ xǐhuan tǐyù ma?","Thành tích của anh ấy ngày càng tốt. Tiểu Tuyết, con có thích thể thao không?"],["xue","喜欢！我们学校的男生都爱打球。","Xǐhuan! Wǒmen xuéxiào de nánshēng dōu ài dǎqiú.","Thích ạ! Các bạn nam trường con đều mê chơi bóng."],["liu","我去拿瓶啤酒，给你拿一瓶饮料。","Wǒ qù ná píng píjiǔ, gěi nǐ ná yì píng yǐnliào.","Bố đi lấy chai bia, lấy cho con một chai nước ngọt nhé."]]}],"g":[{"t":"Câu mục đích 为了……","e":"为了 + mục đích，(chủ ngữ) + hành động: để…, vì…","x":[["为了这次比赛，我每天都去练习。","Wèile zhè cì bǐsài, wǒ měi tiān dōu qù liànxí."],["为了身体健康，他天天跑步。","Wèile shēntǐ jiànkāng, tā tiāntiān pǎobù."]]},{"t":"Bổ ngữ khả năng","e":"Động từ + 得/不 + bổ ngữ kết quả/xu hướng: có thể / không thể làm được. 打得好 (đánh tốt được), 打不好 (đánh không tốt được), 听不懂 (nghe không hiểu).","x":[["打不好没关系。","Dǎ bu hǎo méi guānxi."],["我紧张得打不了球了。","Wǒ jǐnzhāng de dǎ bu liǎo qiú le."],["你听得懂吗？","Nǐ tīng de dǒng ma?"]]},{"t":"Mẫu 越 A 越 B","e":"越 A 越 B: càng A càng B. B thay đổi theo A.","x":[["我越想越紧张。","Wǒ yuè xiǎng yuè jǐnzhāng."],["雨越下越大。","Yǔ yuè xià yuè dà."],["汉语越学越有意思。","Hànyǔ yuè xué yuè yǒu yìsi."]]}],"f":[{"s":"___这次比赛，我每天都去练习。","a":"为了","o":["因为","所以","如果"]},{"s":"打___好没关系，主要是参加。","a":"不","o":["没","得","很"]},{"s":"我越想___紧张。","a":"越","o":["更","很","最"]},{"s":"这个运动员是___第一。","a":"世界","o":["国家","体育","比赛"]},{"s":"你看，你已经___了！","a":"得分","o":["得到","参加","受到"]}],"tf":[{"t":1,"s":"阮明想参加网球比赛。","py":"Ruǎn Míng xiǎng cānjiā wǎngqiú bǐsài.","a":"√"},{"t":1,"s":"阮明网球打得很好。","py":"Ruǎn Míng wǎngqiú dǎ de hěn hǎo.","a":"×"},{"t":2,"s":"比赛的时候阮明很紧张。","py":"Bǐsài de shíhou Ruǎn Míng hěn jǐnzhāng.","a":"√"},{"t":3,"s":"刘先生给小雪拿了一瓶啤酒。","py":"Liú xiānsheng gěi Xiǎoxuě ná le yì píng píjiǔ.","a":"×"}],"q":[{"s":"Để chuẩn bị thi đấu, Minh làm gì?","a":"每天下午去球场练习","o":["每天早上跑步","看奥运会"]},{"s":"Theo Đại Trung, điều quan trọng nhất là gì?","a":"参加","o":["得第一","得分"]}]},{"n":10,"zh":"你明天再把书还给我","py":"Nǐ míngtiān zài bǎ shū huán gěi wǒ","vi":"Mai bạn trả sách cho mình cũng được","goal":["Nói về việc học, ghi chép, hỏi bài.","Dùng câu chữ 把 (1)(2).","Dùng mẫu “在……上/中/下”."],"w":[["把","bǎ","giới từ","(giới từ đưa tân ngữ lên trước động từ)"],["办公室","bàngōngshì","danh từ","văn phòng"],["笔记","bǐjì","danh từ","ghi chép"],["遍","biàn","lượng từ","lượt, lần (từ đầu đến cuối)"],["差","chà","tính từ","kém"],["当然","dāngrán","phó từ","đương nhiên"],["对话","duìhuà","danh từ","hội thoại"],["复习","fùxí","động từ","ôn tập"],["黑板","hēibǎn","danh từ","bảng đen"],["后年","hòunián","danh từ","năm kia (sau năm sau)"],["讲","jiǎng","động từ","giảng, nói"],["句","jù","lượng từ","câu"],["句子","jùzi","danh từ","câu"],["历史","lìshǐ","danh từ","lịch sử"],["明白","míngbai","động từ","hiểu"],["难","nán","tính từ","khó"],["年级","niánjí","danh từ","khối, lớp"],["努力","nǔlì","tính từ","cố gắng"],["清楚","qīngchu","tính từ","rõ ràng"],["认真","rènzhēn","tính từ","chăm chỉ, nghiêm túc"],["数学","shùxué","danh từ","toán học"],["提高","tígāo","động từ","nâng cao"],["外语","wàiyǔ","danh từ","ngoại ngữ"],["要求","yāoqiú","danh từ","yêu cầu"],["页","yè","lượng từ","trang"],["一般","yìbān","tính từ","thông thường"],["遇到","yùdào","động từ","gặp phải"],["作业","zuòyè","danh từ","bài tập"]],"p":[],"t":[{"s":"Ở lớp, một bạn hỏi Tiểu Tuyết cách học toán.","bg":"class","l":[["tx","小雪，你的数学越来越好了，能不能讲讲你的学习方法？","Xiǎoxuě, nǐ de shùxué yuè lái yuè hǎo le, néng bu néng jiǎngjiang nǐ de xuéxí fāngfǎ?","Tiểu Tuyết, môn toán của cậu ngày càng giỏi, cậu kể phương pháp học của cậu được không?"],["xue","没什么特别的，就是上课认真听，把笔记记好。","Méi shénme tèbié de, jiùshì shàngkè rènzhēn tīng, bǎ bǐjì jì hǎo.","Không có gì đặc biệt, chỉ là trên lớp chăm chú nghe giảng, ghi chép đầy đủ."],["tx","我看过你的笔记，写得又清楚又好。","Wǒ kànguo nǐ de bǐjì, xiě de yòu qīngchu yòu hǎo.","Mình xem vở ghi của cậu rồi, vừa rõ ràng vừa đẹp."],["xue","老师写在黑板上的题都很重要，我都把它们记在本子上。","Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, wǒ dōu bǎ tāmen jì zài běnzi shang.","Những bài cô viết lên bảng đều rất quan trọng, mình đều ghi hết vào vở."],["tx","你能把笔记本借给我看看吗？","Nǐ néng bǎ bǐjìběn jiè gěi wǒ kànkan ma?","Cậu cho mình mượn vở ghi xem được không?"],["xue","当然可以，你明天再把书还给我就行。","Dāngrán kěyǐ, nǐ míngtiān zài bǎ shū huán gěi wǒ jiù xíng.","Tất nhiên rồi, mai cậu trả sách cho mình là được."]]},{"s":"Hai bạn làm bài tập gặp câu khó.","bg":"class","l":[["tx","这几道题你会做吗？","Zhè jǐ dào tí nǐ huì zuò ma?","Mấy bài này cậu làm được không?"],["xue","对不起，我也不会。我们一起去办公室问问老师吧。","Duìbuqǐ, wǒ yě bú huì. Wǒmen yìqǐ qù bàngōngshì wènwèn lǎoshī ba.","Xin lỗi, mình cũng không biết làm. Chúng mình cùng lên văn phòng hỏi cô đi."],["tx","好，我们先把作业做完，再去问。","Hǎo, wǒmen xiān bǎ zuòyè zuòwán, zài qù wèn.","Được, chúng mình làm xong bài tập trước rồi đi hỏi."],["xue","遇到难题的时候，问老师是最好的办法。","Yùdào nántí de shíhou, wèn lǎoshī shì zuì hǎo de bànfǎ.","Khi gặp bài khó, hỏi thầy cô là cách tốt nhất."]]},{"s":"Ở văn phòng giáo viên.","bg":"office","l":[["tx","老师，书上有几个问题我们不明白。","Lǎoshī, shū shang yǒu jǐ ge wèntí wǒmen bù míngbai.","Cô ơi, trong sách có mấy câu chúng em chưa hiểu ạ."],["wang","坐吧，哪几个问题？","Zuò ba, nǎ jǐ ge wèntí?","Ngồi đi, những câu nào?"],["tx","第五页的对话，我不明白，小雪也不懂。","Dì-wǔ yè de duìhuà, wǒ bù míngbai, Xiǎoxuě yě bù dǒng.","Bài hội thoại ở trang 5 ạ, em không hiểu, Tiểu Tuyết cũng không hiểu."],["wang","这几个句子我上课讲过，我再讲一遍。","Zhè jǐ ge jùzi wǒ shàngkè jiǎngguo, wǒ zài jiǎng yí biàn.","Mấy câu này cô giảng trên lớp rồi, cô giảng lại một lượt nhé."],["xue","我终于明白了！在老师的帮助下，这些题一点儿也不难。","Wǒ zhōngyú míngbai le! Zài lǎoshī de bāngzhù xià, zhèxiē tí yìdiǎnr yě bù nán.","Cuối cùng em đã hiểu rồi! Nhờ cô giúp, những bài này chẳng khó chút nào."]]}],"g":[{"t":"Câu chữ 把 (1)","e":"Chủ ngữ + 把 + tân ngữ + động từ + thành phần khác (了, bổ ngữ…): nhấn mạnh việc xử lý một vật cụ thể. Động từ không đứng một mình.","x":[["把笔记记好。","Bǎ bǐjì jì hǎo."],["我们先把作业做完。","Wǒmen xiān bǎ zuòyè zuòwán."],["把书还给我。","Bǎ shū huán gěi wǒ."]]},{"t":"Câu chữ 把 (2)","e":"Chủ ngữ + 把 + A + động từ + 在/给/到 + B: đặt/đưa/trả A vào/cho/đến B.","x":[["我把它们记在本子上。","Wǒ bǎ tāmen jì zài běnzi shang."],["你能把笔记本借给我吗？","Nǐ néng bǎ bǐjìběn jiè gěi wǒ ma?"],["请把书放到桌子上。","Qǐng bǎ shū fàngdào zhuōzi shang."]]},{"t":"Mẫu “在……上/中/下”","e":"在……上 (về mặt…), 在……中 (trong quá trình…), 在……下 (dưới sự…, nhờ có…).","x":[["在学习上","Zài xuéxí shang"],["在生活中","Zài shēnghuó zhōng"],["在老师的帮助下","Zài lǎoshī de bāngzhù xià"]]}],"f":[{"s":"你明天再___书还给我。","a":"把","o":["被","给","对"]},{"s":"我都把它们记___本子上。","a":"在","o":["到","给","了"]},{"s":"我再讲一___。","a":"遍","o":["次","回","本"]},{"s":"___老师的帮助下，这些题一点儿也不难。","a":"在","o":["对","把","给"]},{"s":"上课要___听，把笔记记好。","a":"认真","o":["努力","清楚","一般"]}],"tf":[{"t":1,"s":"小雪的数学越来越好。","py":"Xiǎoxuě de shùxué yuè lái yuè hǎo.","a":"√"},{"t":1,"s":"小雪不愿意借笔记本。","py":"Xiǎoxuě bú yuànyì jiè bǐjìběn.","a":"×"},{"t":2,"s":"小雪会做这几道题。","py":"Xiǎoxuě huì zuò zhè jǐ dào tí.","a":"×"},{"t":3,"s":"不懂的是第五页的对话。","py":"Bù dǒng de shì dìwǔ yè de duìhuà.","a":"√"}],"q":[{"s":"Bí quyết học toán của Tiểu Tuyết là gì?","a":"认真听课，记好笔记","o":["每天做很多题","上网查"]},{"s":"Gặp bài khó, các bạn làm gì?","a":"去办公室问老师","o":["问爸爸妈妈","不做了"]}]},{"n":11,"zh":"看来我没办法解决这个问题","py":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí","vi":"Có vẻ tôi không giải quyết được việc này","goal":["Nói về công việc văn phòng: họp, gửi email, xin nghỉ.","Phân biệt 还是 và 或者.","Dùng cụm cố định 看来.","Dùng câu chữ 把 (3) và mẫu 对……来说."],"w":[["办法","bànfǎ","danh từ","cách, biện pháp"],["笔记本（电脑）","bǐjìběn (diànnǎo)","danh từ","máy tính xách tay"],["别人","biérén","đại từ","người khác"],["城市","chéngshì","danh từ","thành phố"],["地点","dìdiǎn","danh từ","địa điểm"],["发","fā","động từ","gửi"],["后天","hòutiān","danh từ","ngày kia"],["会议","huìyì","danh từ","cuộc họp"],["或","huò","liên từ","hoặc"],["或者","huòzhě","liên từ","hoặc là"],["机会","jīhuì","danh từ","cơ hội"],["解决","jiějué","động từ","giải quyết"],["经理","jīnglǐ","danh từ","giám đốc"],["开会","kāihuì","động từ","họp"],["看来","kànlái","động từ","xem ra, có vẻ"],["离开","líkāi","động từ","rời khỏi"],["怕","pà","động từ","sợ"],["请假","qǐngjià","động từ","xin nghỉ"],["生活","shēnghuó","danh từ","cuộc sống"],["声音","shēngyīn","danh từ","âm thanh"],["室","shì","danh từ","phòng"],["同事","tóngshì","danh từ","đồng nghiệp"],["为","wèi","giới từ","vì, cho"],["休假","xiūjià","động từ","nghỉ phép"],["邮箱","yóuxiāng","danh từ","hộp thư"],["愿意","yuànyì","động từ","sẵn lòng"],["只能","zhǐ néng","","chỉ có thể"]],"p":[["老张","Lǎo Zhāng","","anh Trương (đồng nghiệp)"]],"t":[{"s":"Ở công ty của anh Lưu.","bg":"office","l":[["liu","下午的会几点开？","Xiàwǔ de huì jǐ diǎn kāi?","Cuộc họp chiều nay mấy giờ bắt đầu?"],["zhang","经理下午没时间，会议不开了。","Jīnglǐ xiàwǔ méi shíjiān, huìyì bù kāi le.","Giám đốc chiều nay không có thời gian, không họp nữa."],["liu","那什么时候开？","Nà shénme shíhou kāi?","Vậy khi nào họp?"],["zhang","后天上午十点，地点也换了，在一号会议室。我马上给大家发邮件。","Hòutiān shàngwǔ shí diǎn, dìdiǎn yě huàn le, zài yī hào huìyìshì. Wǒ mǎshàng gěi dàjiā fā yóujiàn.","Mười giờ sáng ngày kia, địa điểm cũng đổi rồi, ở phòng họp số 1. Tôi gửi email cho mọi người ngay."],["liu","开会的时候用会议室的电脑还是带自己的笔记本？","Kāihuì de shíhou yòng huìyìshì de diànnǎo háishi dài zìjǐ de bǐjìběn?","Lúc họp dùng máy tính của phòng họp hay mang máy xách tay của mình?"],["zhang","用会议室的或者自己的都行。","Yòng huìyìshì de huòzhě zìjǐ de dōu xíng.","Dùng máy của phòng họp hay của mình đều được."]]},{"s":"Chuẩn bị máy tính cho cuộc họp.","bg":"office","l":[["liu","电脑准备好了吗？","Diànnǎo zhǔnbèi hǎo le ma?","Máy tính chuẩn bị xong chưa?"],["zhang","准备好了，你开机看看有没有问题。","Zhǔnbèi hǎo le, nǐ kāijī kànkan yǒu méiyǒu wèntí.","Xong rồi, anh mở máy xem có vấn đề gì không."],["liu","怎么没有声音？","Zěnme méiyǒu shēngyīn?","Sao lại không có tiếng nhỉ?"],["zhang","看来我没办法解决这个问题，我们只能找别人帮忙了。","Kànlái wǒ méi bànfǎ jiějué zhège wèntí, wǒmen zhǐ néng zhǎo biérén bāngmáng le.","Xem ra tôi không giải quyết được việc này rồi, chúng ta chỉ có thể nhờ người khác thôi."],["liu","别怕，我先把电脑关了，再开一次试试。","Bié pà, wǒ xiān bǎ diànnǎo guānle, zài kāi yí cì shìshi.","Đừng lo, tôi tắt máy đi rồi bật lại thử xem."]]},{"s":"Nhiều đồng nghiệp xin nghỉ, anh Lưu phải làm thêm.","bg":"office","l":[["liu","小王呢？今天怎么没来？","Xiǎo Wáng ne? Jīntiān zěnme méi lái?","Tiểu Vương đâu? Sao hôm nay không đến?"],["zhang","他家里有事，请假了。","Tā jiā li yǒu shì, qǐngjià le.","Nhà cậu ấy có việc, xin nghỉ rồi."],["liu","好几个同事都休假了，我怕开会前做不完这些工作。","Hǎojǐ ge tóngshì dōu xiūjià le, wǒ pà kāihuì qián zuò bu wán zhèxiē gōngzuò.","Mấy đồng nghiệp đều nghỉ phép, tôi sợ trước cuộc họp không làm xong những việc này."],["zhang","已经十二点了，我们先去吃饭吧。对我来说，吃饭比什么都重要！","Yǐjīng shí'èr diǎn le, wǒmen xiān qù chī fàn ba. Duì wǒ lái shuō, chī fàn bǐ shénme dōu zhòngyào!","Mười hai giờ rồi, chúng ta đi ăn trước đã. Đối với tôi, ăn là quan trọng nhất!"],["liu","你们先去，我得把这个发到经理的邮箱里。","Nǐmen xiān qù, wǒ děi bǎ zhège fā dào jīnglǐ de yóuxiāng li.","Các anh đi trước đi, tôi phải gửi cái này vào hộp thư của giám đốc."]]}],"g":[{"t":"Phân biệt 还是 và 或者","e":"还是 dùng trong câu hỏi lựa chọn: A 还是 B？ 或者 dùng trong câu trần thuật: A 或者 B 都行.","x":[["用会议室的电脑还是带自己的？","Yòng huìyìshì de diànnǎo háishi dài zìjǐ de?"],["用会议室的或者自己的都行。","Yòng huìyìshì de huòzhě zìjǐ de dōu xíng."]]},{"t":"Cụm cố định 看来","e":"看来 + nhận định: xem ra, có vẻ như (rút ra từ tình hình thực tế).","x":[["看来我没办法解决这个问题。","Kànlái wǒ méi bànfǎ jiějué zhège wèntí."],["看来要下雨了。","Kànlái yào xià yǔ le."]]},{"t":"Câu chữ 把 (3)","e":"Chủ ngữ + 把 + tân ngữ + động từ + 了 / bổ ngữ: nhấn mạnh kết quả xử lý.","x":[["我先把电脑关了。","Wǒ xiān bǎ diànnǎo guānle."],["我得把这个发到经理的邮箱里。","Wǒ děi bǎ zhège fā dào jīnglǐ de yóuxiāng li."]]},{"t":"Mẫu 对……来说","e":"对 + người + 来说: đối với ai đó mà nói.","x":[["对我来说，吃饭比什么都重要。","Duì wǒ lái shuō, chī fàn bǐ shénme dōu zhòngyào."],["对学生来说，学习最重要。","Duì xuésheng lái shuō, xuéxí zuì zhòngyào."]]}],"f":[{"s":"开会用会议室的电脑___带自己的笔记本？","a":"还是","o":["或者","和","也"]},{"s":"用会议室的___自己的都行。","a":"或者","o":["还是","和","跟"]},{"s":"___我没办法解决这个问题。","a":"看来","o":["看起来","好像","如果"]},{"s":"他家里有事，___了。","a":"请假","o":["休假","开会","离开"]},{"s":"___我来说，吃饭比什么都重要。","a":"对","o":["给","为","跟"]}],"tf":[{"t":1,"s":"下午的会议不开了。","py":"Xiàwǔ de huìyì bù kāi le.","a":"√"},{"t":1,"s":"会议改到明天上午。","py":"Huìyì gǎi dào míngtiān shàngwǔ.","a":"×"},{"t":2,"s":"电脑没有声音。","py":"Diànnǎo méiyǒu shēngyīn.","a":"√"},{"t":3,"s":"小王今天休假了。","py":"Xiǎo Wáng jīntiān xiūjià le.","a":"×"}],"q":[{"s":"Cuộc họp chuyển sang lúc nào?","a":"后天上午十点","o":["明天下午","今天下午"]},{"s":"Vì sao anh Lưu chưa đi ăn?","a":"要把文件发给经理","o":["不饿","要开会"]}]},{"n":12,"zh":"这个季节天气变化很快","py":"Zhège jìjié tiānqì biànhuà hěn kuài","vi":"Mùa này thời tiết thay đổi rất nhanh","goal":["Nói về bốn mùa, thời tiết và sự thay đổi.","Dùng câu lựa chọn 或者……，或者…….","Dùng nghĩa mở rộng của bổ ngữ xu hướng (2)(3).","Dùng phó từ phạm vi 就 (chỉ)."],"w":[["变","biàn","động từ","biến, thay đổi"],["变成","biànchéng","động từ","biến thành"],["变化","biànhuà","danh từ","sự thay đổi"],["常常","chángcháng","phó từ","thường thường"],["船","chuán","danh từ","thuyền"],["春天","chūntiān","danh từ","mùa xuân"],["地方","dìfang","danh từ","nơi, chỗ"],["冬天","dōngtiān","danh từ","mùa đông"],["风","fēng","danh từ","gió"],["刚才","gāngcái","danh từ","vừa nãy"],["工作日","gōngzuòrì","danh từ","ngày làm việc"],["公园","gōngyuán","danh từ","công viên"],["刮","guā","động từ","thổi (gió)"],["关注","guānzhù","động từ","quan tâm, theo dõi"],["季节","jìjié","danh từ","mùa"],["街","jiē","danh từ","phố"],["借","jiè","động từ","mượn, cho mượn"],["开花","kāihuā","động từ","nở hoa"],["凉快","liángkuai","tính từ","mát mẻ"],["秋天","qiūtiān","danh từ","mùa thu"],["伞","sǎn","danh từ","ô, dù"],["四季","sìjì","danh từ","bốn mùa"],["夏天","xiàtiān","danh từ","mùa hè"],["新闻","xīnwén","danh từ","tin tức"],["叶子","yèzi","danh từ","lá cây"],["雨衣","yǔyī","danh từ","áo mưa"]],"p":[],"t":[{"s":"Mùa xuân, Anna và cô Vương đi dạo.","bg":"park","l":[["anna","王老师，您看，这条街上的树都开花了！","Wáng lǎoshī, nín kàn, zhè tiáo jiē shang de shù dōu kāihuā le!","Cô Vương ơi, cô xem, cây trên con phố này đều nở hoa rồi!"],["wang","上个星期我去公园划船，那儿的花也开了。","Shàng ge xīngqī wǒ qù gōngyuán huáchuán, nàr de huā yě kāi le.","Tuần trước cô đi công viên chèo thuyền, hoa ở đó cũng nở rồi."],["anna","天气真好，我下午也想去公园划船。","Tiānqì zhēn hǎo, wǒ xiàwǔ yě xiǎng qù gōngyuán huáchuán.","Thời tiết đẹp quá, chiều nay em cũng muốn đến công viên chèo thuyền."],["wang","去吧！今天是工作日，人应该不多。","Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","Đi đi! Hôm nay là ngày làm việc, chắc không đông người đâu."],["anna","您有时间吗？我想跟您一起去。","Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.","Cô có rảnh không ạ? Em muốn đi cùng cô."],["wang","我下午有课。或者明天，或者后天，我给你打电话。","Wǒ xiàwǔ yǒu kè. Huòzhě míngtiān, huòzhě hòutiān, wǒ gěi nǐ dǎ diànhuà.","Chiều nay cô có tiết. Hoặc ngày mai, hoặc ngày kia, cô sẽ gọi cho em."]]},{"s":"Trời đột nhiên nổi gió.","bg":"street","l":[["anna","刚才还是晴天，怎么突然刮起风来了？","Gāngcái hái shì qíng tiān, zěnme tūrán guā qi fēng lai le?","Vừa nãy trời còn nắng, sao tự nhiên nổi gió thế?"],["wang","这个季节天气变化很快，看来要下雨了。","Zhège jìjié tiānqì biànhuà hěn kuài, kànlái yào xià yǔ le.","Mùa này thời tiết thay đổi rất nhanh, xem ra sắp mưa rồi."],["anna","我没带伞，也没带雨衣。","Wǒ méi dài sǎn, yě méi dài yǔyī.","Em không mang ô, cũng không mang áo mưa."],["wang","我包里有一把伞，借给你吧。","Wǒ bāo lǐ yǒu yì bǎ sǎn, jiè gěi nǐ ba.","Trong túi cô có một cái ô, cho em mượn nhé."],["anna","谢谢！我们快走回去吧。","Xièxie! Wǒmen kuài zǒu huiqu ba.","Em cảm ơn cô! Chúng ta mau đi về thôi."]]},{"s":"Lê Hoa đã ở Bắc Kinh hơn một năm.","bg":"cafe","l":[["anna","你来北京一年多了，习惯了吗？","Nǐ lái Běijīng yì nián duō le, xíguàn le ma?","Cậu đến Bắc Kinh hơn một năm rồi, quen chưa?"],["hua","别的都习惯了，就天气还不太习惯。","Biéde dōu xíguàn le, jiù tiānqì hái bú tài xíguàn.","Cái khác đều quen rồi, chỉ có thời tiết là chưa quen lắm."],["anna","为什么？你不喜欢这儿的四季吗？","Wèishénme? Nǐ bù xǐhuan zhèr de sìjì ma?","Tại sao? Cậu không thích bốn mùa ở đây à?"],["hua","我觉得冬天太冷了。不过秋天很凉快，叶子都变成黄色的，特别漂亮。","Wǒ juéde dōngtiān tài lěng le. Búguò qiūtiān hěn liángkuai, yèzi dōu biànchéng huángsè de, tèbié piàoliang.","Mình thấy mùa đông lạnh quá. Nhưng mùa thu rất mát, lá cây đều chuyển sang màu vàng, cực kỳ đẹp."],["anna","我常常关注新闻，听说今年很多地方雪都少了。","Wǒ chángcháng guānzhù xīnwén, tīngshuō jīnnián hěn duō dìfang xuě dōu shǎo le.","Mình hay theo dõi tin tức, nghe nói năm nay nhiều nơi tuyết rơi ít hơn."]]}],"g":[{"t":"Câu lựa chọn 或者……，或者……","e":"或者 A，或者 B: hoặc A, hoặc B (đưa ra các khả năng).","x":[["或者明天，或者后天，我给你打电话。","Huòzhě míngtiān, huòzhě hòutiān, wǒ gěi nǐ dǎ diànhuà."],["我们或者坐地铁，或者打车。","Wǒmen huòzhě zuò dìtiě, huòzhě dǎchē."]]},{"t":"Nghĩa mở rộng của bổ ngữ xu hướng (2)","e":"Động từ + 起 + tân ngữ + 来: bắt đầu xảy ra (刮起风来, 下起雨来, 笑起来).","x":[["怎么突然刮起风来了？","Zěnme tūrán guā qi fēng lai le?"],["外面下起雨来了。","Wàimian xià qi yǔ lai le."]]},{"t":"Nghĩa mở rộng của bổ ngữ xu hướng (3)","e":"变成, 走回去…: bổ ngữ chỉ kết quả biến đổi hoặc quay về.","x":[["叶子都变成黄色的。","Yèzi dōu biànchéng huángsè de."],["我们快走回去吧。","Wǒmen kuài zǒu huiqu ba."]]},{"t":"Phó từ phạm vi 就","e":"就 = chỉ, riêng có (nhấn mạnh phạm vi hẹp).","x":[["别的都习惯了，就天气还不太习惯。","Biéde dōu xíguàn le, jiù tiānqì hái bú tài xíguàn."],["我就有一把伞。","Wǒ jiù yǒu yì bǎ sǎn."]]}],"f":[{"s":"或者明天，___后天，我给你打电话。","a":"或者","o":["还是","和","也"]},{"s":"怎么突然刮___风来了？","a":"起","o":["上","下","出"]},{"s":"我包里有一把伞，___给你吧。","a":"借","o":["还","送","买"]},{"s":"秋天叶子都___黄色的。","a":"变成","o":["变化","关注","开花"]},{"s":"这个季节天气___很快。","a":"变化","o":["变成","开花","关注"]}],"tf":[{"t":1,"s":"街上的树都开花了。","py":"Jiēshàng de shù dōu kāihuā le.","a":"√"},{"t":1,"s":"王老师下午有课。","py":"Wáng lǎoshī xiàwǔ yǒu kè.","a":"√"},{"t":2,"s":"安娜带了伞。","py":"Ānnà dài le sǎn.","a":"×"},{"t":3,"s":"黎花已经习惯了北京的天气。","py":"Lí Huā yǐjīng xíguàn le Běijīng de tiānqì.","a":"×"}],"q":[{"s":"Cô Vương cho Anna mượn gì?","a":"一把伞","o":["一件雨衣","一件大衣"]},{"s":"Lê Hoa thấy mùa thu thế nào?","a":"很凉快，叶子很漂亮","o":["太冷了","太热了"]}]},{"n":13,"zh":"我的新邻居来自英国","py":"Wǒ de xīn línjū láizì Yīngguó","vi":"Hàng xóm mới của tôi đến từ Anh","goal":["Nói về hàng xóm, mời khách đến nhà, văn hóa ẩm thực Bắc – Nam.","Dùng câu giả thiết “……的话，就……”.","Dùng câu chữ 把 (4).","Dùng câu song song 一边……，一边……."],"w":[["北方","běifāng","danh từ","miền Bắc"],["不同","bù tóng","","khác nhau"],["的话","dehuà","trợ từ","nếu… thì"],["地图","dìtú","danh từ","bản đồ"],["点","diǎn","động từ","gọi (món)"],["东方","dōngfāng","danh từ","phương Đông"],["放","fàng","động từ","đặt, để"],["放心","fàngxīn","động từ","yên tâm"],["夫妻","fūqī","danh từ","vợ chồng"],["感到","gǎndào","động từ","cảm thấy"],["画家","huàjiā","danh từ","họa sĩ"],["加","jiā","động từ","thêm"],["酒","jiǔ","danh từ","rượu"],["客人","kèrén","danh từ","khách"],["来自","láizì","động từ","đến từ"],["礼物","lǐwù","danh từ","quà"],["聊天儿","liáotiānr","động từ","tán gẫu"],["邻居","línjū","danh từ","hàng xóm"],["南方","nánfāng","danh từ","miền Nam"],["盘子","pánzi","danh từ","cái đĩa"],["请客","qǐngkè","động từ","mời, khao"],["晚会","wǎnhuì","danh từ","dạ hội, bữa tiệc tối"],["文化","wénhuà","danh từ","văn hóa"],["一边","yìbiān","phó từ","vừa… vừa…"],["直到","zhídào","động từ","mãi đến"],["做法","zuòfǎ","danh từ","cách làm"],["做客","zuòkè","động từ","làm khách"]],"p":[["英国","Yīngguó","","nước Anh"]],"t":[{"s":"Ở nhà hàng, anh Lưu mời đồng nghiệp ăn.","bg":"restaurant","l":[["liu","今天我请客，你们想吃什么就点什么！","Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","Hôm nay tôi mời, các anh muốn ăn gì thì gọi nấy!"],["zhang","那我就不客气了。听说这家的鱼很特别。","Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā de yú hěn tèbié.","Vậy tôi không khách sáo nhé. Nghe nói món cá ở quán này rất đặc biệt."],["liu","对，南方菜跟北方菜的做法不同。除了鱼，还加什么菜？","Duì, nánfāng cài gēn běifāng cài de zuòfǎ bù tóng. Chúle yú, hái jiā shénme cài?","Đúng thế, món miền Nam và món miền Bắc có cách nấu khác nhau. Ngoài cá còn gọi thêm món gì?"],["zhang","我们就三个人，不用点那么多。","Wǒmen jiù sān ge rén, búyòng diǎn nàme duō.","Chúng ta chỉ có ba người, không cần gọi nhiều thế."],["liu","好的，先点这些。下个星期我儿子过生日，有时间的话，就来我家做客吧。","Hǎo de, xiān diǎn zhèxiē. Xià ge xīngqī wǒ érzi guò shēngrì, yǒu shíjiān de huà, jiù lái wǒ jiā zuòkè ba.","Được, gọi những món này trước. Tuần sau là sinh nhật con trai tôi, nếu rảnh thì đến nhà tôi chơi nhé."]]},{"s":"Lần đầu mời hàng xóm mới đến nhà.","bg":"home","l":[["wang","第一次请新邻居来做客，我总担心有什么没准备好。","Dì-yī cì qǐng xīn línjū lái zuòkè, wǒ zǒng dānxīn yǒu shénme méi zhǔnbèi hǎo.","Lần đầu mời hàng xóm mới đến nhà, em cứ lo có gì chưa chuẩn bị chu đáo."],["liu","放心吧，菜都准备好了，就是还差一瓶酒。","Fàngxīn ba, cài dōu zhǔnbèi hǎo le, jiùshì hái chà yì píng jiǔ.","Yên tâm đi, đồ ăn đã chuẩn bị xong rồi, chỉ còn thiếu một chai rượu."],["wang","他们夫妻俩来自英国，丈夫是画家，对东方文化很感兴趣。","Tāmen fūqī liǎ láizì Yīngguó, zhàngfu shì huàjiā, duì dōngfāng wénhuà hěn gǎn xìngqù.","Hai vợ chồng họ đến từ Anh, người chồng là họa sĩ, rất thích văn hóa phương Đông."],["liu","那我们一边吃饭，一边聊天儿吧。","Nà wǒmen yìbiān chī fàn, yìbiān liáotiānr ba.","Vậy chúng ta vừa ăn vừa trò chuyện nhé."]]},{"s":"Bữa tiệc sinh nhật Tiểu Thiên.","bg":"home","l":[["zhang","小天，生日快乐！这是我送你的礼物。","Xiǎotiān, shēngrì kuàilè! Zhè shì wǒ sòng nǐ de lǐwù.","Tiểu Thiên, chúc mừng sinh nhật! Đây là quà chú tặng cháu."],["tian","谢谢！我现在可以打开吗？","Xièxie! Wǒ xiànzài kěyǐ dǎkāi ma?","Cháu cảm ơn chú! Bây giờ cháu mở ra được không ạ?"],["zhang","当然。你妈妈说你跟你姐姐一样喜欢画画儿。","Dāngrán. Nǐ māma shuō nǐ gēn nǐ jiějie yíyàng xǐhuan huà huàr.","Tất nhiên rồi. Mẹ cháu bảo cháu cũng thích vẽ tranh như chị."],["tian","是的，我以后想当画家！哇，是画笔，我太喜欢了！","Shì de, wǒ yǐhòu xiǎng dāng huàjiā! Wā, shì huàbǐ, wǒ tài xǐhuan le!","Vâng ạ, sau này cháu muốn làm họa sĩ! Oa, là bút vẽ, cháu thích lắm!"],["wang","我去把盘子拿来，咱们一边吃蛋糕一边聊天儿，直到晚会结束。","Wǒ qù bǎ pánzi ná lai, zánmen yìbiān chī dàngāo yìbiān liáotiānr, zhídào wǎnhuì jiéshù.","Em đi lấy đĩa nhé, mọi người vừa ăn bánh vừa trò chuyện cho đến khi tiệc kết thúc."]]}],"g":[{"t":"Câu giả thiết “……的话，就……”","e":"(如果)……的话，(chủ ngữ) 就……: nếu… thì… Hay dùng trong khẩu ngữ.","x":[["有时间的话，就来我家做客吧。","Yǒu shíjiān de huà, jiù lái wǒ jiā zuòkè ba."],["下雨的话，我们就不去了。","Xià yǔ de huà, wǒmen jiù bú qù le."]]},{"t":"Câu chữ 把 (4)","e":"把 + tân ngữ + động từ + 来/去: mang/đưa cái gì đến/đi.","x":[["我去把盘子拿来。","Wǒ qù bǎ pánzi ná lai."],["请把这本书带去。","Qǐng bǎ zhè běn shū dàiqu."]]},{"t":"Câu song song 一边……，一边……","e":"一边 A，一边 B: vừa làm A vừa làm B (cùng lúc).","x":[["我们一边吃饭，一边聊天儿。","Wǒmen yìbiān chī fàn, yìbiān liáotiānr."],["他一边听音乐一边写作业。","Tā yìbiān tīng yīnyuè yìbiān xiě zuòyè."]]}],"f":[{"s":"有时间___，就来我家做客吧。","a":"的话","o":["如果","时候","以后"]},{"s":"我们一边吃饭，___聊天儿。","a":"一边","o":["一起","一样","一直"]},{"s":"我去___盘子拿来。","a":"把","o":["被","给","对"]},{"s":"他们夫妻俩___英国。","a":"来自","o":["来到","从","在"]},{"s":"今天我___，你们想吃什么就点什么！","a":"请客","o":["做客","客人","客气"]}],"tf":[{"t":1,"s":"南方菜跟北方菜的做法不同。","py":"Nánfāng cài gēn běifāng cài de zuòfǎ bù tóng.","a":"√"},{"t":1,"s":"他们点了很多菜。","py":"Tāmen diǎn le hěn duō cài.","a":"×"},{"t":2,"s":"新邻居是法国人。","py":"Xīn línjū shì Fǎguó rén.","a":"×"},{"t":3,"s":"小天想当画家。","py":"Xiǎotiān xiǎng dāng huàjiā.","a":"√"}],"q":[{"s":"Người chồng hàng xóm mới làm nghề gì?","a":"画家","o":["老师","医生"]},{"s":"Tiểu Thiên nhận được quà gì?","a":"画笔","o":["蛋糕","书"]}]},{"n":14,"zh":"这本书被别人借走了","py":"Zhè běn shū bèi biérén jièzǒu le","vi":"Quyển sách này đã bị người khác mượn mất","goal":["Nói về thư viện, tiết mục văn nghệ, việc đọc sách.","Dùng câu bị động với 被.","Dùng câu nối tiếp 先……，再/然后…….","Dùng mẫu “× 什么（啊）” để phản bác."],"w":[["班级","bānjí","danh từ","lớp học"],["报纸","bàozhǐ","danh từ","báo"],["被","bèi","giới từ","bị, được"],["表演","biǎoyǎn","động từ","biểu diễn"],["词典","cídiǎn","danh từ","từ điển"],["电子书","diànzǐshū","danh từ","sách điện tử"],["故事","gùshi","danh từ","câu chuyện"],["节","jié","lượng từ","tiết (học)"],["节目","jiémù","danh từ","tiết mục"],["留学生","liúxuéshēng","danh từ","du học sinh"],["面前","miànqián","danh từ","trước mặt"],["名人","míngrén","danh từ","người nổi tiếng"],["女生","nǚshēng","danh từ","nữ sinh"],["然后","ránhòu","liên từ","sau đó"],["视频","shìpín","danh từ","video"],["跳","tiào","động từ","nhảy"],["图书馆","túshūguǎn","danh từ","thư viện"],["网站","wǎngzhàn","danh từ","trang web"],["忘记","wàngjì","động từ","quên"],["相信","xiāngxìn","động từ","tin tưởng"],["校长","xiàozhǎng","danh từ","hiệu trưởng"],["新年","xīnnián","danh từ","năm mới"],["一块儿","yíkuàir","phó từ","cùng nhau"],["有些","yǒuxiē","đại từ","một số"],["怎么办","zěnme bàn","","làm thế nào"],["最好","zuìhǎo","phó từ","tốt nhất là"],["最后","zuìhòu","danh từ","cuối cùng"]],"p":[],"t":[{"s":"Ở thư viện, Minh tìm một quyển sách.","bg":"library","l":[["ming","您好，我想借这本关于名人的故事书。","Nín hǎo, wǒ xiǎng jiè zhè běn guānyú míngrén de gùshi shū.","Chào cô, em muốn mượn quyển sách kể chuyện về những người nổi tiếng này."],["staff","对不起，这本书被别人借走了。","Duìbuqǐ, zhè běn shū bèi biérén jièzǒu le.","Xin lỗi, quyển này đã bị người khác mượn mất rồi."],["ming","怎么办？明天上课要用。","Zěnme bàn? Míngtiān shàngkè yào yòng.","Làm sao bây giờ? Mai đi học em cần dùng."],["staff","你可以先在我们的网站上看电子书，然后下个星期再来借。","Nǐ kěyǐ xiān zài wǒmen de wǎngzhàn shang kàn diànzǐshū, ránhòu xià ge xīngqī zài lái jiè.","Em có thể đọc sách điện tử trên trang web của thư viện trước, sau đó tuần sau lại đến mượn."],["ming","好主意！谢谢您！","Hǎo zhǔyi! Xièxie nín!","Ý hay quá! Em cảm ơn cô!"]]},{"s":"Lớp chuẩn bị tiết mục cho buổi liên hoan năm mới.","bg":"class","l":[["wang","新年晚会每个班级都要表演一个节目，我们班表演什么？","Xīnnián wǎnhuì měi ge bānjí dōu yào biǎoyǎn yí ge jiémù, wǒmen bān biǎoyǎn shénme?","Dạ hội năm mới, mỗi lớp đều phải biểu diễn một tiết mục, lớp mình biểu diễn gì?"],["hua","我们几个女生想一块儿跳个舞。","Wǒmen jǐ ge nǚshēng xiǎng yíkuàir tiào ge wǔ.","Mấy bạn nữ chúng em muốn cùng nhảy một bài."],["ming","跳什么舞啊！我们留学生最好唱一首中文歌。","Tiào shénme wǔ a! Wǒmen liúxuéshēng zuì hǎo chàng yì shǒu Zhōngwén gē.","Nhảy gì chứ! Du học sinh chúng em tốt nhất là hát một bài hát tiếng Trung."],["wang","都很好！先唱歌，再跳舞。校长也会来看。","Dōu hěn hǎo! Xiān chànggē, zài tiàowǔ. Xiàozhǎng yě huì lái kàn.","Đều hay cả! Hát trước, nhảy sau. Thầy hiệu trưởng cũng sẽ đến xem."]]},{"s":"Sau buổi biểu diễn.","bg":"class","l":[["anna","我差点儿忘记歌词了，在校长面前特别紧张。","Wǒ chàdiǎnr wàngjì gēcí le, zài xiàozhǎng miànqián tèbié jǐnzhāng.","Mình suýt nữa quên lời bài hát, trước mặt thầy hiệu trưởng căng thẳng lắm."],["hua","我相信大家都没看出来。有些同学还拍了视频。","Wǒ xiāngxìn dàjiā dōu méi kàn chūlai. Yǒuxiē tóngxué hái pāile shìpín.","Mình tin là mọi người không nhận ra đâu. Còn có bạn quay video nữa."],["ming","最后的舞跳得最好，大家都在报纸上看到了！","Zuìhòu de wǔ tiào de zuì hǎo, dàjiā dōu zài bàozhǐ shang kàndào le!","Bài nhảy cuối cùng là hay nhất, mọi người đều thấy trên báo rồi!"],["anna","是吗？我去图书馆找那张报纸。","Shì ma? Wǒ qù túshūguǎn zhǎo nà zhāng bàozhǐ.","Thật à? Mình ra thư viện tìm tờ báo đó đây."]]}],"g":[{"t":"Câu bị động với 被","e":"Chủ ngữ (người/vật chịu tác động) + 被 + (người làm) + động từ + thành phần khác. Người làm có thể bỏ.","x":[["这本书被别人借走了。","Zhè běn shū bèi biérén jièzǒu le."],["我的自行车被骑走了。","Wǒ de zìxíngchē bèi qízǒu le."],["蛋糕被吃完了。","Dàngāo bèi chīwán le."]]},{"t":"Câu nối tiếp 先……，再/然后……","e":"先 A，再/然后 B: trước làm A, sau đó làm B.","x":[["先在网站上看电子书，然后再来借。","Xiān zài wǎngzhàn shang kàn diànzǐshū, ránhòu zài lái jiè."],["先唱歌，再跳舞。","Xiān chànggē, zài tiàowǔ."]]},{"t":"Mẫu “× 什么（啊）”","e":"Động từ/tính từ + 什么（啊）: phản bác, không đồng ý với ý kiến người khác.","x":[["跳什么舞啊！","Tiào shénme wǔ a!"],["贵什么啊，一点儿也不贵。","Guì shénme a, yìdiǎnr yě bú guì."]]}],"f":[{"s":"这本书___别人借走了。","a":"被","o":["把","给","让"]},{"s":"你可以先看电子书，___再来借。","a":"然后","o":["最后","以后","后来"]},{"s":"我们几个女生想一块儿___个舞。","a":"跳","o":["唱","表演","看"]},{"s":"我差点儿___歌词了。","a":"忘记","o":["相信","记得","表演"]},{"s":"我___大家都没看出来。","a":"相信","o":["担心","忘记","怕"]}],"tf":[{"t":1,"s":"阮明借到了那本书。","py":"Ruǎn Míng jiè dào le nà běn shū.","a":"×"},{"t":1,"s":"图书馆的网站上有电子书。","py":"Túshūguǎn de wǎngzhàn shang yǒu diànzǐshū.","a":"√"},{"t":2,"s":"留学生想唱一首中文歌。","py":"Liúxuésheng xiǎng chàng yì shǒu Zhōngwén gē.","a":"√"},{"t":3,"s":"安娜表演的时候一点儿也不紧张。","py":"Ānnà biǎoyǎn de shíhou yìdiǎnr yě bù jǐnzhāng.","a":"×"}],"q":[{"s":"Quyển sách Minh muốn mượn đâu rồi?","a":"被别人借走了","o":["丢了","在网站上"]},{"s":"Thứ tự biểu diễn thế nào?","a":"先唱歌，再跳舞","o":["先跳舞，再唱歌","只唱歌"]}]},{"n":15,"zh":"我是半个河内人","py":"Wǒ shì bàn ge Hénèi rén","vi":"Tôi gần như là người Hà Nội","goal":["Giới thiệu khu nhà, thành phố và điểm du lịch.","Dùng giới từ 根据.","Dùng lặp số lượng từ “一 + lượng từ + 一 + lượng từ”.","Dùng cụm cố định 在……看来 và 不一会儿."],"w":[["草地","cǎodì","danh từ","bãi cỏ"],["段","duàn","lượng từ","đoạn"],["放学","fàngxué","động từ","tan học"],["附近","fùjìn","danh từ","gần đây, lân cận"],["根据","gēnjù","giới từ","căn cứ, dựa theo"],["关系","guānxì","danh từ","quan hệ"],["河","hé","danh từ","sông"],["经过","jīngguò","động từ","đi qua"],["景点","jǐngdiǎn","danh từ","điểm tham quan"],["可是","kěshì","liên từ","nhưng"],["蓝","lán","tính từ","xanh lam"],["老人","lǎorén","danh từ","người già"],["聊","liáo","động từ","trò chuyện"],["了解","liǎojiě","động từ","tìm hiểu, hiểu"],["马路","mǎlù","danh từ","đường cái"],["平时","píngshí","danh từ","ngày thường"],["外地","wàidì","danh từ","nơi khác"],["西北","xīběi","danh từ","tây bắc"],["养","yǎng","động từ","nuôi"],["以上","yǐshàng","danh từ","trở lên"],["游客","yóukè","danh từ","du khách"],["游戏","yóuxì","danh từ","trò chơi"],["有名","yǒumíng","tính từ","nổi tiếng"],["遇见","yùjiàn","động từ","gặp gỡ"]],"p":[["河内","Hénèi","","Hà Nội"],["还剑湖","Huánjiàn Hú","","hồ Hoàn Kiếm"]],"t":[{"s":"Anna hỏi Lê Hoa về khu nhà ở Hà Nội.","bg":"campus","l":[["anna","你家住的那个小区怎么样？","Nǐ jiā zhù de nàge xiǎoqū zěnmeyàng?","Khu nhà cậu ở thế nào?"],["hua","环境挺好的，买东西也很方便，马路对面就是超市。","Huánjìng tǐng hǎo de, mǎi dōngxi yě hěn fāngbiàn, mǎlù duìmiàn jiùshì chāoshì.","Môi trường khá tốt, mua sắm cũng tiện, đối diện bên kia đường là siêu thị."],["anna","孩子们平时在哪儿玩儿？","Háizimen píngshí zài nǎr wánr?","Ngày thường trẻ con chơi ở đâu?"],["hua","小区里有很多树和草地，放学以后孩子们就在那儿玩儿游戏。","Xiǎoqū lǐ yǒu hěn duō shù hé cǎodì, fàngxué yǐhòu háizimen jiù zài nàr wánr yóuxì.","Trong khu có nhiều cây và bãi cỏ, tan học là bọn trẻ chơi trò chơi ở đó."],["anna","老人多吗？","Lǎorén duō ma?","Có nhiều người già không?"],["hua","挺多的。很多人养小狗，经过草地的时候常常遇见他们。","Tǐng duō de. Hěn duō rén yǎng xiǎo gǒu, jīngguò cǎodì de shíhou chángcháng yùjiàn tāmen.","Khá nhiều. Nhiều người nuôi chó con, đi qua bãi cỏ hay gặp họ lắm."]]},{"s":"Anna định đi Hà Nội du lịch.","bg":"cafe","l":[["anna","假期我想去河内旅游，可是对河内不太了解。","Jiàqī wǒ xiǎng qù Hénèi lǚyóu, kěshì duì Hénèi bú tài liǎojiě.","Kỳ nghỉ mình muốn đi du lịch Hà Nội, nhưng không hiểu nhiều về Hà Nội."],["da","黎花虽然不是在河内出生的，但是在那儿上了大学，算是半个河内人。","Lí Huā suīrán bú shì zài Hénèi chūshēng de, dànshì zài nàr shàngle dàxué, suànshì bàn ge Hénèi rén.","Lê Hoa tuy không sinh ra ở Hà Nội, nhưng học đại học ở đó, coi như nửa người Hà Nội."],["hua","对！根据我的了解，河内有一千多年的历史。","Duì! Gēnjù wǒ de liǎojiě, Hénèi yǒu yìqiān duō nián de lìshǐ.","Đúng thế! Theo mình biết, Hà Nội có lịch sử hơn một nghìn năm."],["anna","有什么有名的景点？","Yǒu shénme yǒumíng de jǐngdiǎn?","Có những điểm tham quan nào nổi tiếng?"],["hua","还剑湖最有名，每年有很多外地游客。一个一个地说，得说半天。","Huánjiàn Hú zuì yǒumíng, měi nián yǒu hěn duō wàidì yóukè. Yí ge yí ge de shuō, děi shuō bàn tiān.","Hồ Hoàn Kiếm nổi tiếng nhất, mỗi năm có rất nhiều du khách từ nơi khác đến. Kể từng chỗ một thì phải nói cả buổi."]]},{"s":"Tối ở Hà Nội, các bạn đi dạo.","bg":"street","l":[["anna","这条河真蓝！我们沿着河走一段吧。","Zhè tiáo hé zhēn lán! Wǒmen yánzhe hé zǒu yí duàn ba.","Dòng sông này xanh quá! Chúng mình đi dọc sông một đoạn nhé."],["hua","好。在我看来，河内的晚上比白天更漂亮。","Hǎo. Zài wǒ kànlái, Hénèi de wǎnshang bǐ báitiān gèng piàoliang.","Được. Theo mình, Hà Nội buổi tối còn đẹp hơn ban ngày."],["anna","我们聊一会儿天吧，我想多了解河内人的生活。","Wǒmen liáo yíhuìr tiān ba, wǒ xiǎng duō liǎojiě Hénèi rén de shēnghuó.","Chúng mình trò chuyện một lát nhé, mình muốn hiểu thêm về cuộc sống của người Hà Nội."],["hua","不一会儿，前面就到还剑湖了。","Bù yíhuìr, qiánmian jiù dào Huánjiàn Hú le.","Chẳng mấy chốc, phía trước đã là hồ Hoàn Kiếm rồi."]]}],"g":[{"t":"Giới từ 根据","e":"根据 + căn cứ: dựa theo, căn cứ vào…","x":[["根据我的了解，河内有一千多年的历史。","Gēnjù wǒ de liǎojiě, Hénèi yǒu yìqiān duō nián de lìshǐ."],["根据天气，我们决定明天出发。","Gēnjù tiānqì, wǒmen juédìng míngtiān chūfā."]]},{"t":"Lặp số lượng từ","e":"一 + lượng từ + 一 + lượng từ (+ 地): lần lượt từng…, từng cái một.","x":[["一个一个地说","Yí ge yí ge de shuō"],["一步一步地学","Yí bù yí bù de xué"],["一天一天地过去了","Yì tiān yì tiān de guòqu le"]]},{"t":"Cụm cố định 在……看来","e":"在 + người + 看来: theo ý kiến của ai đó.","x":[["在我看来，河内的晚上更漂亮。","Zài wǒ kànlái, Hénèi de wǎnshang gèng piàoliang."],["在老师看来，这个问题不难。","Zài lǎoshī kànlái, zhège wèntí bù nán."]]},{"t":"Cụm cố định 不一会儿","e":"不一会儿: chẳng mấy chốc, một lát sau.","x":[["不一会儿，前面就到了。","Bù yíhuìr, qiánmian jiù dào le."],["不一会儿，雨就停了。","Bù yíhuìr, yǔ jiù tíng le."]]}],"f":[{"s":"___我的了解，河内有一千多年的历史。","a":"根据","o":["对于","关于","为了"]},{"s":"一个___个地说，得说半天。","a":"一","o":["两","每","个"]},{"s":"在我___，河内的晚上比白天更漂亮。","a":"看来","o":["来说","觉得","认为"]},{"s":"放学以后孩子们就在那儿玩儿___。","a":"游戏","o":["景点","游客","马路"]},{"s":"马路对面___是超市。","a":"就","o":["才","也","还"]}],"tf":[{"t":1,"s":"黎花家的小区附近有超市。","py":"Lí Huā jiā de xiǎoqū fùjìn yǒu chāoshì.","a":"√"},{"t":2,"s":"黎花是在河内出生的。","py":"Lí Huā shì zài Hénèi chūshēng de.","a":"×"},{"t":2,"s":"还剑湖是河内最有名的景点。","py":"Huánjiàn Hú shì Hénèi zuì yǒumíng de jǐngdiǎn.","a":"√"},{"t":3,"s":"黎花觉得河内的白天比晚上更漂亮。","py":"Lí Huā juéde Hénèi de báitiān bǐ wǎnshang gèng piàoliang.","a":"×"}],"q":[{"s":"Trẻ con trong khu nhà chơi ở đâu?","a":"树下和草地上","o":["马路上","超市里"]},{"s":"Theo Lê Hoa, Hà Nội có lịch sử bao lâu?","a":"一千多年","o":["两千多年","五百多年"]}]},{"n":16,"zh":"我听说有的熊猫出国了","py":"Wǒ tīngshuō yǒude xióngmāo chūguó le","vi":"Nghe nói có những chú gấu trúc đã ra nước ngoài","goal":["Nói về động vật, gấu trúc – quốc bảo của Trung Quốc.","Dùng câu song song “一会儿……，一会儿……”.","Dùng giới từ 关于 và cụm 一般来说.","Dùng câu so sánh (11): A 像 B 一样……."],"w":[["半天","bàntiān","danh từ","nửa ngày, rất lâu"],["饱","bǎo","tính từ","no"],["大人","dàren","danh từ","người lớn"],["大熊猫","dàxióngmāo","danh từ","gấu trúc lớn"],["动物","dòngwù","danh từ","động vật"],["动物园","dòngwùyuán","danh từ","vườn thú"],["关于","guānyú","giới từ","về (việc gì)"],["国宝","guóbǎo","danh từ","quốc bảo"],["好像","hǎoxiàng","động từ","giống như"],["脚","jiǎo","danh từ","bàn chân"],["可爱","kě'ài","tính từ","đáng yêu"],["脸","liǎn","danh từ","mặt"],["其实","qíshí","phó từ","thực ra"],["奇怪","qíguài","tính từ","kỳ lạ"],["全","quán","phó từ","toàn bộ"],["认得","rènde","động từ","nhận ra, biết"],["身边","shēnbiān","danh từ","bên cạnh"],["喜爱","xǐ'ài","động từ","yêu thích"],["野生","yěshēng","tính từ","hoang dã"],["一会儿","yíhuìr","số lượng từ","lúc thì, một lát"],["脏","zāng","tính từ","bẩn"],["张","zhāng","động từ","mở, há (miệng)"],["照顾","zhàogù","động từ","chăm sóc"],["周末","zhōumò","danh từ","cuối tuần"],["竹子","zhúzi","danh từ","cây tre, trúc"],["嘴","zuǐ","danh từ","miệng"]],"p":[],"t":[{"s":"Tiểu Thiên hỏi mẹ về gấu trúc.","bg":"home","l":[["tian","妈妈，大熊猫为什么只吃竹子，不吃肉？","Māma, dàxióngmāo wèishénme zhǐ chī zhúzi, bù chī ròu?","Mẹ ơi, sao gấu trúc chỉ ăn tre mà không ăn thịt ạ?"],["wang","其实它们像我们一样，也能吃肉，只是不喜欢吃。","Qíshí tāmen xiàng wǒmen yíyàng, yě néng chī ròu, zhǐshì bù xǐhuan chī.","Thực ra chúng cũng giống chúng ta, cũng ăn được thịt, chỉ là không thích ăn thôi."],["tian","为什么大熊猫是中国的国宝？","Wèishénme dàxióngmāo shì Zhōngguó de guóbǎo?","Sao gấu trúc lại là quốc bảo của Trung Quốc ạ?"],["wang","只有中国有野生的大熊猫。","Zhǐyǒu Zhōngguó yǒu yěshēng de dàxióngmāo.","Chỉ có Trung Quốc mới có gấu trúc hoang dã."],["tian","我听说有的熊猫出国了，它们去哪儿了？","Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?","Con nghe nói có những con gấu trúc đã ra nước ngoài, chúng đi đâu ạ?"],["wang","关于这件事，说来话长，我一点儿一点儿告诉你吧。","Guānyú zhè jiàn shì, shuō lái huà cháng, wǒ yìdiǎnr yìdiǎnr gàosu nǐ ba.","Chuyện này dài lắm, mẹ kể dần dần cho con nghe nhé."]]},{"s":"Ở quán cà phê mèo, Tiểu Tuyết hỏi nhân viên.","bg":"cafe","l":[["xue","这只小猫你们照顾多长时间了？","Zhè zhī xiǎo māo nǐmen zhàogu duō cháng shíjiān le?","Các anh chị chăm con mèo này bao lâu rồi ạ?"],["staff","一年多了。刚发现它的时候，它又脏又小。","Yì nián duō le. Gāng fāxiàn tā de shíhou, tā yòu zāng yòu xiǎo.","Hơn một năm rồi. Lúc mới thấy nó, nó vừa bẩn vừa bé."],["xue","现在它又干净又漂亮！","Xiànzài tā yòu gānjìng yòu piàoliang!","Giờ nó vừa sạch vừa xinh!"],["staff","是啊，它一会儿睡在你脚边，一会儿爬到你身上，可爱极了。","Shì a, tā yíhuìr shuì zài nǐ jiǎo biān, yíhuìr pá dào nǐ shēnshang, kě'ài jíle.","Đúng vậy, nó lúc thì ngủ cạnh chân em, lúc thì trèo lên người em, đáng yêu cực kỳ."],["xue","妈妈，我们也养一只小猫吧？","Māma, wǒmen yě yǎng yì zhī xiǎo māo ba?","Mẹ ơi, mình cũng nuôi một con mèo đi?"],["wang","我们没有时间照顾它。周末我带你们去动物园看动物吧。","Wǒmen méiyǒu shíjiān zhàogu tā. Zhōumò wǒ dài nǐmen qù dòngwùyuán kàn dòngwù ba.","Nhà mình không có thời gian chăm nó. Cuối tuần mẹ đưa các con đi vườn thú xem động vật nhé."]]},{"s":"Ở vườn thú, cả nhà xem gấu trúc.","bg":"park","l":[["xue","这只大熊猫一会儿爬上去，一会儿爬下来，太可爱了！","Zhè zhī dàxióngmāo yíhuìr pá shangqu, yíhuìr pá xialai, tài kě'ài le!","Con gấu trúc này lúc thì trèo lên, lúc thì trèo xuống, đáng yêu quá!"],["tian","它好像还没吃饱，张着嘴在找竹子。","Tā hǎoxiàng hái méi chī bǎo, zhāngzhe zuǐ zài zhǎo zhúzi.","Hình như nó vẫn chưa no, đang há miệng tìm tre kìa."],["wang","你看它的脸，好像在笑。","Nǐ kàn tā de liǎn, hǎoxiàng zài xiào.","Con xem mặt nó, giống như đang cười ấy."],["tian","奇怪，大人和小孩儿全都认得大熊猫！","Qíguài, dàrén hé xiǎoháir quán dōu rènde dàxióngmāo!","Lạ thật, người lớn và trẻ con đều nhận ra gấu trúc!"],["wang","一般来说，大熊猫是最受人们喜爱的动物。","Yìbān lái shuō, dàxióngmāo shì zuì shòu rénmen xǐ'ài de dòngwù.","Nói chung, gấu trúc là con vật được mọi người yêu thích nhất."]]}],"g":[{"t":"Câu song song “一会儿……，一会儿……”","e":"一会儿 A，一会儿 B: lúc thì A, lúc thì B (hai việc thay nhau).","x":[["它一会儿睡在你脚边，一会儿爬到你身上。","Tā yíhuìr shuì zài nǐ jiǎo biān, yíhuìr pá dào nǐ shēnshang."],["天气一会儿冷，一会儿热。","Tiānqì yíhuìr lěng, yíhuìr rè."]]},{"t":"Giới từ 关于","e":"关于 + chủ đề: về… (giới thiệu nội dung được nói tới).","x":[["关于这件事，说来话长。","Guānyú zhè jiàn shì, shuō lái huà cháng."],["我在看一本关于熊猫的书。","Wǒ zài kàn yì běn guānyú xióngmāo de shū."]]},{"t":"Cụm cố định 一般来说","e":"一般来说: nói chung, thông thường mà nói.","x":[["一般来说，大熊猫是最受喜爱的动物。","Yìbān lái shuō, dàxióngmāo shì zuì shòu xǐ'ài de dòngwù."],["一般来说，冬天北方比南方冷。","Yìbān lái shuō, dōngtiān běifāng bǐ nánfāng lěng."]]},{"t":"Câu so sánh (11): 像……一样","e":"A + 像 + B + 一样 (+ tính từ/động từ): A giống B.","x":[["它们像我们一样，也能吃肉。","Tāmen xiàng wǒmen yíyàng, yě néng chī ròu."],["她像妈妈一样漂亮。","Tā xiàng māma yíyàng piàoliang."]]}],"f":[{"s":"它们___我们一样，也能吃肉。","a":"像","o":["跟","比","对"]},{"s":"___这件事，说来话长。","a":"关于","o":["对于","根据","为了"]},{"s":"它一会儿爬上去，___爬下来。","a":"一会儿","o":["一边","一起","一样"]},{"s":"___来说，大熊猫是最受喜爱的动物。","a":"一般","o":["其实","奇怪","全"]},{"s":"我们没有时间___它。","a":"照顾","o":["关心","喜爱","认得"]}],"tf":[{"t":1,"s":"大熊猫不能吃肉。","py":"Dàxióngmāo bù néng chī ròu.","a":"×"},{"t":1,"s":"只有中国有野生大熊猫。","py":"Zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo.","a":"√"},{"t":2,"s":"那只小猫以前又脏又小。","py":"Nà zhī xiǎo māo yǐqián yòu zāng yòu xiǎo.","a":"√"},{"t":3,"s":"他们周末去动物园。","py":"Tāmen zhōumò qù dòngwùyuán.","a":"√"}],"q":[{"s":"Vì sao gia đình không nuôi mèo?","a":"没有时间照顾","o":["小猫太脏","房子太小"]},{"s":"Con gấu trúc ở vườn thú đang làm gì?","a":"一会儿爬上去，一会儿爬下来","o":["睡觉","吃肉"]}]},{"n":17,"zh":"我要多向认真的人学习","py":"Wǒ yào duō xiàng rènzhēn de rén xuéxí","vi":"Tôi phải học hỏi nhiều từ những người chăm chỉ","goal":["Nói về du học, học ngoại ngữ, ý kiến và lời khuyên.","Dùng giới từ 向.","Dùng câu hỏi tu từ “不是……吗？”.","Dùng câu tăng tiến “……，更……” và câu điều kiện 只有……，才……."],"w":[["比如","bǐrú","động từ","ví dụ như"],["查","chá","động từ","tra"],["常见","cháng jiàn","","thường gặp"],["聪明","cōngming","tính từ","thông minh"],["错","cuò","danh từ","lỗi, cái sai"],["到处","dàochù","phó từ","khắp nơi"],["方向","fāngxiàng","danh từ","phương hướng"],["关机","guānjī","động từ","tắt máy"],["国家","guójiā","danh từ","quốc gia"],["害怕","hàipà","động từ","sợ hãi"],["回答","huídá","động từ","trả lời"],["继续","jìxù","động từ","tiếp tục"],["可","kě","phó từ","thật là (nhấn mạnh)"],["留学","liúxué","động từ","du học"],["楼梯","lóutī","danh từ","cầu thang"],["难题","nántí","danh từ","vấn đề khó"],["前天","qiántiān","danh từ","hôm kia"],["认为","rènwéi","động từ","cho rằng"],["容易","róngyì","tính từ","dễ"],["生气","shēngqì","động từ","tức giận"],["同意","tóngyì","động từ","đồng ý"],["屋子","wūzi","danh từ","căn phòng"],["向","xiàng","giới từ","hướng về, với"],["有关","yǒuguān","động từ","có liên quan"],["有用","yǒuyòng","tính từ","có ích"],["真正","zhēnzhèng","tính từ","thực sự"],["只有","zhǐyǒu","liên từ","chỉ có"]],"p":[],"t":[{"s":"Minh bị lạc đường ở thành phố mới.","bg":"street","l":[["ming","我好像找不到方向了，手机也关机了。","Wǒ hǎoxiàng zhǎo bu dào fāngxiàng le, shǒujī yě guānjī le.","Hình như mình bị lạc hướng rồi, điện thoại cũng tắt máy."],["hua","别害怕，我们可以向别人问路。","Bié hàipà, wǒmen kěyǐ xiàng biérén wèn lù.","Đừng sợ, chúng mình có thể hỏi đường người khác."],["ming","我前天也在这儿走错了，到处都是一样的楼。","Wǒ qiántiān yě zài zhèr zǒucuò le, dàochù dōu shì yíyàng de lóu.","Hôm kia mình cũng đi nhầm ở đây, chỗ nào cũng là những tòa nhà giống nhau."],["hua","你不是有地图吗？","Nǐ bú shì yǒu dìtú ma?","Chẳng phải cậu có bản đồ sao?"],["ming","对啊！我怎么没想到。你可真聪明！","Duì a! Wǒ zěnme méi xiǎngdào. Nǐ kě zhēn cōngming!","Đúng rồi! Sao mình không nghĩ ra nhỉ. Cậu thông minh thật đấy!"]]},{"s":"Anna và Đại Trung nói về du học.","bg":"cafe","l":[["anna","你认为去哪个国家留学比较好？","Nǐ rènwéi qù nǎge guójiā liúxué bǐjiào hǎo?","Cậu cho rằng đi du học nước nào thì tốt?"],["da","我认为最好去说那种外语的国家，这样学得更快，更容易。","Wǒ rènwéi zuì hǎo qù shuō nà zhǒng wàiyǔ de guójiā, zhèyàng xué de gèng kuài, gèng róngyì.","Mình cho rằng tốt nhất là đến nước nói ngoại ngữ đó, như vậy học nhanh hơn, dễ hơn."],["anna","我同意。比如学汉语，在中国学就比在法国学好得多。","Wǒ tóngyì. Bǐrú xué Hànyǔ, zài Zhōngguó xué jiù bǐ zài Fǎguó xué hǎo de duō.","Mình đồng ý. Ví dụ học tiếng Trung, học ở Trung Quốc tốt hơn học ở Pháp nhiều."],["da","只有多说多练，才能真正学好外语。","Zhǐyǒu duō shuō duō liàn, cái néng zhēnzhèng xuéhǎo wàiyǔ.","Chỉ có nói nhiều, luyện nhiều mới thực sự học giỏi ngoại ngữ."]]},{"s":"Minh hỏi cô Vương về lỗi sai thường gặp.","bg":"office","l":[["ming","老师，我的作文有很多错，您生气了吗？","Lǎoshī, wǒ de zuòwén yǒu hěn duō cuò, nín shēngqì le ma?","Cô ơi, bài văn của em có nhiều lỗi, cô có giận không ạ?"],["wang","不生气。有错不是很正常吗？你查查词典，再改一改。","Bù shēngqì. Yǒu cuò bú shì hěn zhèngcháng ma? Nǐ cháchá cídiǎn, zài gǎi yì gǎi.","Không giận. Có lỗi chẳng phải là bình thường sao? Em tra từ điển rồi sửa lại nhé."],["ming","这些都是常见的错，我要多向认真的同学学习。","Zhèxiē dōu shì chángjiàn de cuò, wǒ yào duō xiàng rènzhēn de tóngxué xuéxí.","Đây đều là những lỗi thường gặp, em phải học hỏi nhiều từ các bạn chăm chỉ."],["wang","对，遇到难题也别怕，继续努力，学的东西都会有用的。","Duì, yùdào nántí yě bié pà, jìxù nǔlì, xué de dōngxi dōu huì yǒuyòng de.","Đúng vậy, gặp vấn đề khó cũng đừng sợ, tiếp tục cố gắng, những gì học được đều sẽ có ích."]]}],"g":[{"t":"Giới từ 向","e":"向 + người/hướng + động từ: hướng về, với (ai). 向……学习 = học hỏi ai; 向……问路 = hỏi đường ai.","x":[["我们可以向别人问路。","Wǒmen kěyǐ xiàng biérén wèn lù."],["我要多向认真的同学学习。","Wǒ yào duō xiàng rènzhēn de tóngxué xuéxí."],["向前走。","Xiàng qián zǒu."]]},{"t":"Câu hỏi tu từ “不是……吗？”","e":"不是……吗？ dùng để khẳng định một điều cả hai đều biết: chẳng phải… sao?","x":[["你不是有地图吗？","Nǐ bú shì yǒu dìtú ma?"],["有错不是很正常吗？","Yǒu cuò bú shì hěn zhèngcháng ma?"]]},{"t":"Câu tăng tiến “……，更……”","e":"Vế sau dùng 更 để tăng mức độ: …, càng… hơn.","x":[["这样学得更快，更容易。","Zhèyàng xué de gèng kuài, gèng róngyì."],["他很聪明，更努力。","Tā hěn cōngming, gèng nǔlì."]]},{"t":"Câu điều kiện 只有……，才……","e":"只有 + điều kiện duy nhất，才 + kết quả: chỉ có… mới…","x":[["只有多说多练，才能真正学好外语。","Zhǐyǒu duō shuō duō liàn, cái néng zhēnzhèng xuéhǎo wàiyǔ."],["只有努力，才能成功。","Zhǐyǒu nǔlì, cái néng chénggōng."]]}],"f":[{"s":"我们可以___别人问路。","a":"向","o":["对","给","往"]},{"s":"你___有地图吗？","a":"不是","o":["没有","是不是","不会"]},{"s":"___多说多练，才能真正学好外语。","a":"只有","o":["只要","因为","如果"]},{"s":"我___最好去说那种外语的国家。","a":"认为","o":["以为","同意","回答"]},{"s":"遇到难题也别怕，___努力。","a":"继续","o":["一直","到处","真正"]}],"tf":[{"t":1,"s":"阮明的手机关机了。","py":"Ruǎn Míng de shǒujī guānjī le.","a":"√"},{"t":1,"s":"阮明没有地图。","py":"Ruǎn Míng méiyǒu dìtú.","a":"×"},{"t":2,"s":"安娜同意大中的看法。","py":"Ānnà tóngyì Dàzhōng de kànfǎ.","a":"√"},{"t":3,"s":"王老师看了阮明的作文很生气。","py":"Wáng lǎoshī kànle Ruǎn Míng de zuòwén hěn shēngqì.","a":"×"}],"q":[{"s":"Theo Đại Trung, muốn học giỏi ngoại ngữ thì sao?","a":"多说多练","o":["多看书","多上网"]},{"s":"Cô Vương bảo Minh sửa lỗi thế nào?","a":"查词典，再改一改","o":["问同学","重写一遍"]}]},{"n":18,"zh":"我学会了包饺子","py":"Wǒ xuéhuìle bāo jiǎozi","vi":"Tôi đã học được cách gói sủi cảo","goal":["Nói về lễ Tết, gói sủi cảo, kế hoạch và mục tiêu.","Biểu đạt số ước lượng (三四个, 二十多…).","Phân biệt 刚才 và 刚刚 / 刚.","Dùng câu điều kiện 只要……，就……; mẫu 从……起."],"w":[["阿姨","āyí","danh từ","cô, dì"],["毕业","bìyè","động từ","tốt nghiệp"],["不久","bùjiǔ","tính từ","không lâu"],["出发","chūfā","động từ","xuất phát"],["出生","chūshēng","động từ","sinh ra"],["大概","dàgài","phó từ","khoảng, có lẽ"],["懂得","dǒngde","động từ","hiểu, biết"],["发生","fāshēng","động từ","xảy ra"],["发展","fāzhǎn","động từ","phát triển"],["刚","gāng","phó từ","vừa mới"],["刚刚","gānggāng","phó từ","vừa mới"],["过节","guòjié","động từ","ăn lễ, đón tết"],["过去","guòqù","danh từ","quá khứ"],["坚持","jiānchí","động từ","kiên trì"],["见面","jiànmiàn","động từ","gặp mặt"],["节日","jiérì","danh từ","ngày lễ"],["矿泉水","kuàngquánshuǐ","danh từ","nước khoáng"],["联欢","liánhuān","động từ","liên hoan"],["目标","mùbiāo","danh từ","mục tiêu"],["起","qǐ","động từ","bắt đầu (từ)"],["收","shōu","động từ","nhận, thu"],["叔叔","shūshu","danh từ","chú"],["完成","wánchéng","động từ","hoàn thành"],["学期","xuéqī","danh từ","học kỳ"],["怎样","zěnyàng","đại từ","thế nào"],["只要","zhǐyào","liên từ","chỉ cần"],["总","zǒng","phó từ","luôn, mãi"]],"p":[["春节","Chūn Jié","","Tết Nguyên Đán"]],"t":[{"s":"Gần Tết, Đại Trung mời các bạn về nhà.","bg":"campus","l":[["da","春节快到了，你们想不想去我家过节？","Chūn Jié kuài dào le, nǐmen xiǎng bù xiǎng qù wǒ jiā guòjié?","Tết sắp đến rồi, các cậu có muốn về nhà mình ăn Tết không?"],["anna","太好了！什么时候出发？","Tài hǎo le! Shénme shíhou chūfā?","Tuyệt quá! Khi nào xuất phát?"],["da","大概二十八号出发，坐三四个小时车就到了。我妈妈和阿姨都会包饺子。","Dàgài èrshíbā hào chūfā, zuò sān-sì ge xiǎoshí chē jiù dào le. Wǒ māma hé āyí dōu huì bāo jiǎozi.","Khoảng ngày 28 xuất phát, đi xe ba bốn tiếng là đến. Mẹ và dì mình đều biết gói sủi cảo."],["ming","我刚刚收到我妈的信息，她让我好好儿过节。","Wǒ gānggāng shōudào wǒ mā de xìnxī, tā ràng wǒ hǎohāor guòjié.","Mình vừa nhận được tin nhắn của mẹ, mẹ dặn mình ăn Tết vui vẻ."]]},{"s":"Ở nhà Đại Trung, bà dạy gói sủi cảo.","bg":"kitchen","l":[["nai","你们刚来不久，就来学包饺子吧。","Nǐmen gāng lái bùjiǔ, jiù lái xué bāo jiǎozi ba.","Các cháu mới đến chưa lâu, lại đây học gói sủi cảo nào."],["anna","奶奶，饺子怎样包？我从来没包过。","Nǎinai, jiǎozi zěnyàng bāo? Wǒ cónglái méi bāoguo.","Bà ơi, sủi cảo gói thế nào ạ? Cháu chưa gói bao giờ."],["nai","很简单，只要多练几次，就能包好。","Hěn jiǎndān, zhǐyào duō liàn jǐ cì, jiù néng bāo hǎo.","Đơn giản lắm, chỉ cần tập vài lần là gói đẹp được."],["ming","刚才我包了二十多个，都不好看。","Gāngcái wǒ bāole èrshí duō ge, dōu bù hǎokàn.","Vừa nãy cháu gói hơn hai mươi cái, cái nào cũng xấu."],["anna","坚持就是胜利！你看，我学会了包饺子！","Jiānchí jiù shì shènglì! Nǐ kàn, wǒ xuéhuìle bāo jiǎozi!","Kiên trì là chiến thắng! Xem này, mình học được cách gói sủi cảo rồi!"]]},{"s":"Sau Tết, các bạn nói về mục tiêu năm mới.","bg":"cafe","l":[["hua","新学期就要开始了，你们的目标是什么？","Xīn xuéqī jiù yào kāishǐ le, nǐmen de mùbiāo shì shénme?","Học kỳ mới sắp bắt đầu rồi, mục tiêu của các cậu là gì?"],["anna","从这个学期起，我要每天坚持说汉语。","Cóng zhège xuéqī qǐ, wǒ yào měi tiān jiānchí shuō Hànyǔ.","Bắt đầu từ học kỳ này, mình sẽ kiên trì nói tiếng Trung mỗi ngày."],["da","我明年就要毕业了，我希望能完成所有的课。","Wǒ míngnián jiù yào bìyè le, wǒ xīwàng néng wánchéng suǒyǒu de kè.","Sang năm mình tốt nghiệp rồi, mình hy vọng hoàn thành được tất cả các môn."],["ming","过去的一年发生了很多事情，我懂得了很多。只要努力，就会有发展！","Guòqù de yì nián fāshēngle hěn duō shìqing, wǒ dǒngdele hěn duō. Zhǐyào nǔlì, jiù huì yǒu fāzhǎn!","Một năm qua đã xảy ra nhiều chuyện, mình đã hiểu ra nhiều điều. Chỉ cần cố gắng là sẽ tiến bộ!"]]}],"g":[{"t":"Cách biểu đạt số ước lượng","e":"Hai số liền nhau: 三四个 (3–4 cái). Số + 多: 二十多个 (hơn 20). 大概/左右 cũng chỉ ước lượng.","x":[["坐三四个小时车","Zuò sān-sì ge xiǎoshí chē"],["我包了二十多个","Wǒ bāole èrshí duō ge"],["大概二十八号出发","Dàgài èrshíbā hào chūfā"]]},{"t":"Phân biệt 刚才 và 刚刚 / 刚","e":"刚才 là danh từ chỉ thời điểm vừa xong, có thể đứng đầu câu. 刚/刚刚 là phó từ, đứng sau chủ ngữ, trước động từ.","x":[["刚才我包了二十多个。","Gāngcái wǒ bāole èrshí duō ge."],["我刚刚收到信息。","Wǒ gānggāng shōudào xìnxī."],["你们刚来不久。","Nǐmen gāng lái bùjiǔ."]]},{"t":"Câu điều kiện 只要……，就……","e":"只要 + điều kiện đủ，就 + kết quả: chỉ cần… là…","x":[["只要多练几次，就能包好。","Zhǐyào duō liàn jǐ cì, jiù néng bāo hǎo."],["只要努力，就会有发展。","Zhǐyào nǔlì, jiù huì yǒu fāzhǎn."]]},{"t":"Mẫu 从……起","e":"从 + thời điểm + 起: bắt đầu từ…","x":[["从这个学期起，我要每天说汉语。","Cóng zhège xuéqī qǐ, wǒ yào měi tiān shuō Hànyǔ."],["从明天起，我天天跑步。","Cóng míngtiān qǐ, wǒ tiāntiān pǎobù."]]}],"f":[{"s":"___多练几次，就能包好。","a":"只要","o":["只有","如果","因为"]},{"s":"___这个学期起，我要每天坚持说汉语。","a":"从","o":["在","到","向"]},{"s":"___我包了二十多个，都不好看。","a":"刚才","o":["刚","刚刚","过去"]},{"s":"坐三___个小时车就到了。","a":"四","o":["两","五","多"]},{"s":"我明年就要___了。","a":"毕业","o":["出生","出发","发生"]}],"tf":[{"t":1,"s":"他们大概二十八号出发。","py":"Tāmen dàgài èrshíbā hào chūfā.","a":"√"},{"t":2,"s":"安娜以前包过饺子。","py":"Ānnà yǐqián bāoguo jiǎozi.","a":"×"},{"t":2,"s":"阮明包了二十多个饺子。","py":"Ruǎn Míng bāole èrshí duō ge jiǎozi.","a":"√"},{"t":3,"s":"大中今年就要毕业了。","py":"Dàzhōng jīnnián jiù yào bìyè le.","a":"×"}],"q":[{"s":"Đi xe đến nhà Đại Trung mất bao lâu?","a":"三四个小时","o":["一两个小时","七八个小时"]},{"s":"Mục tiêu năm mới của Anna là gì?","a":"每天坚持说汉语","o":["毕业","学包饺子"]}]}]};
